#!/usr/bin/env python3
r"""token_output_gate --- the enforcement half of #951 / #993 / #996.

Invoked through `scripts/ci/check_no_token_in_output`, the shell launcher
repo_lint wires; that file is three lines of dispatch and this one is the
gate.  Run it either way -- the launcher passes its arguments straight
through.

#951 found a live PAT printed in cleartext by a checker's own failure message.
#993 fixed the three sites it could find by grepping `scripts/` for five
variable names and executing every checker that matched under a sentinel
environment.  That is a point-in-time measurement: nothing mechanically stops
the next checker from reintroducing the shape.  This check is the mechanism.

THE RULE

    Under scripts/** and tests/**, a shell source line may not interpolate the
    VALUE of a known credential variable into an output command.

=========================================================================
WHY THIS FILE IS A REBUILD (#1015)
=========================================================================

The first attempt (#1012, closed and parked) decided "is this an output
command, and does this reference reach it" with a hand-written character walk,
and every review round found a NEW shell spelling the walk did not model --
five direct-form escapes were still live at close.  The list of shell spellings
is not a finite thing a reviewer can close by inspection, and 51 hand-written
fixtures could only assert what their author had already thought of.

So the deciding question is not "which constructs should the walk model?"  It
is "does this line put the value on a stream?", and that question is
EXECUTABLE.  This file carries both halves:

  * THE GATE is a STATIC scanner.  It runs in CI over a repository and never
    executes the source it scans.  Executing arbitrary repository source in CI
    would be unsafe, and its behaviour under a runner's environment would say
    nothing about its behaviour anywhere else.

  * THE ORACLE is for the TEST SUITE ONLY (`--self-test`).  For each construct
    in the corpus it writes a disposable fixture carrying an obviously fake
    sentinel in a credential-named variable, runs it under `bash` in a
    throwaway temp tree with a scrubbed environment, captures stdout AND
    stderr separately, and greps both for the sentinel.  That is GROUND TRUTH:
    the construct leaks or it does not, independent of anyone's opinion.  The
    fixtures are generated by this file; no repository source is ever executed.

    It is NOT independent of WHICH bash answers, which is why the interpreter
    is pinned and recorded rather than assumed.  An older bash rejects a
    construct it cannot parse and the oracle scores the rejection as CLEAN --
    on macOS's 3.2 that silently covers `${VAR@A}`, `${VAR@Q}`, `${VAR@P}`,
    `${VAR^^}`, `declare -n` and `|&`, every one of which puts the value on
    stdout under CI's 5.2.  `ORACLE_BASH_MIN` is the floor, the resolved path
    and version print on the summary line, and a run below the floor is
    refused with an environment error instead of producing a number that
    reads like ground truth and is not.  See the block above `run_oracle`.

    It is NOT independent of WHICH VALUE it samples either, and that one is
    still open.  Ground truth is established from a SINGLE sentinel, and that
    sentinel is LETTER-LEADING, so every verdict below was measured at ONE
    point in the value space rather than across credentials.  At least one
    construct's verdict is an artefact of that point: `echo $((GH_TOKEN))`
    reads CLEAN because a LETTER-LEADING operand is a NAME to bash, which
    finds it unset and evaluates it to `0`.  Hand the same line a
    DIGIT-LEADING NON-NUMERIC value and bash writes `9Zq7Xf2Lp: value too
    great for base (error token is "9Zq7Xf2Lp")` to STDERR -- the value,
    reproduced TWICE -- and `run_oracle` greps stderr.  Measured on this head:
    the oracle reports leaks=False under the shipped sentinel and leaks=True
    under a digit-leading one, while the SCANNER reads clean under both.  So
    the construct is an agreeing pair today and would be an UNDECLARED MISS
    the moment the sampled shape changed -- and it is not in `CORPUS` at all.
    (An ALL-DIGIT value reads clean again, because bash evaluates it as a
    number: one shape surfaces this, the other two do not, which is why the
    sweep is a sweep.)  So a construct that measures clean here may leak on a
    value shaped differently, and this corpus would not know.
    It is NOT independent of HOW MUCH of the value reaches the stream, and
    that one has a stated floor.  The oracle greps for WINDOWS as well as the
    whole string, because `${VAR:0:8}` is a partial leak -- and a window has a
    length, below which a real leak measures CLEAN.  At the original eight,
    `echo "${GH_TOKEN:0:7}"` put seven credential characters on stdout and
    read clean, which would have filed the scanner's CORRECT finding under
    conservatism: a real leak recorded in the register of things the gate is
    too strict about (#1032 round 3).  The floor is now four, both sides of it
    are asserted in `_sentinel_window_cases`, and it PRINTS on the summary
    line.  Below the floor the residue is a limit of the MEASUREMENT and is
    named as one -- never smuggled into `KNOWN_BROADER`, which is a register
    of what the SCANNER gets wrong.

    The sampled shape is derived from `SENTINEL` and PRINTS on the
    `--self-test` summary line beside the interpreter and the floor; that
    print is the record, the same way the registries are.  This is the `ORACLE_BASH_MIN`
    problem one axis over -- an unstated dependency of the measurement, on the
    VALUE instead of on the environment -- and unlike that one it is declared
    rather than closed: sweeping the corpus across letter-leading,
    digit-leading and all-digit sentinels is #1036.

    The suite then asserts the static scanner AGREES with the oracle on every
    construct.  A construct the oracle says leaks and the scanner calls clean
    is a FALSE NEGATIVE; a construct the oracle says is clean and the scanner
    flags is scanner conservatism.  Both must be DECLARED in `KNOWN_MISSES` or
    `KNOWN_BROADER` with a written reason, or the suite fails and prints the
    offending line together with the captured streams.  A declared entry that
    stops disagreeing also fails, so neither registry can quietly rot.

    This is the shape `check_doc_ownership` uses with markdown-it-py and the
    shape `markdown-target-parser-is-cmark-gfm` records: measure against the
    real implementation instead of reasoning about a specification.

=========================================================================
WHAT "KNOWN CREDENTIAL VARIABLE" MEANS (#996 design question 1)
=========================================================================

A CLOSED, EXPLICIT NAME LIST (`TOKEN_NAMES` below) -- not a heuristic over
names matching TOKEN / PAT / SECRET / KEY.  Carried unchanged from #1012,
where it survived five review rounds without a finding against it.

The list loses recall: a credential reached under some other name is invisible
to it.  That is the deliberate trade.  This check runs inside repo_lint, which
publishes the REQUIRED `lint` context, and repo_lint propagates to every
consumer repo -- so one false positive reds a required check across the fleet
with no break-glass.  A gate that is right about a smaller set beats one that
is broadly right and occasionally wrong.

The heuristic is also wrong on this tree, not just in principle.  A `*TOKEN*`
name match fires on `SUMMARY_ACK_TOKEN` / `ACK_TOKEN` (the
mergepath-summary-ack marker), `MERGEPATH_EXPECT_READ_GH_TOKEN` and
`STEP_NO_TOKEN` (flags), and `BOOTSTRAP_SKIP_AUTHOR_TOKEN` (a switch) -- none
of which hold credential material.  Every one would need an allow-list entry,
and that allow-list is then the thing nine repos have to get right.

Extending the list is a one-line edit here, in mergepath, which propagates to
every consumer with the rest of the scripts/ci kit.

=========================================================================
HOW LEGITIMATE EMITTERS ARE EXEMPTED (#996 design question 2)
=========================================================================

An INLINE PRAGMA, visible at the site, never a path allow-list:

    printf 'export OP_PREFLIGHT_REVIEWER_PAT=%q\n' "$OP_PREFLIGHT_REVIEWER_PAT"  # TOKEN_OUTPUT_EXEMPT: <reason>

The reason is MANDATORY -- a bare `TOKEN_OUTPUT_EXEMPT:` with nothing after it
still fails, the same hardening `NO_BARE_GH_WRITE_EXEMPT` got in #466.
`scripts/op-preflight.sh` is the canonical legitimate emitter: writing those
values to its cache IS its contract.

The marker counts ONLY inside a real shell comment -- a `#` that is unquoted,
unescaped, word-initial, and at parameter-expansion nesting depth zero.  #1012
was bypassable in two independent ways and both are re-established here as
properties with oracle-backed cases rather than inherited as patches:

  * `printf '%s %s\n' "$GH_TOKEN" 'TOKEN_OUTPUT_EXEMPT: text'` -- the marker is
    quoted DATA.  The command still runs and still writes the value.
  * `echo "$GH_TOKEN" ${UNSET:+ # TOKEN_OUTPUT_EXEMPT: bypass}` -- `${...}` is
    a parameter expansion, not a command context, so bash starts NO comment at
    that `#` and prints the value.

Both are corpus entries, both oracle-confirmed leaking, both flagged.

The pragma is a REVIEW MARKER, not a security boundary.  Anyone editing the
file can silence this check -- by adding the pragma, by renaming the variable,
by any of the indirections below.  What it buys is that every deliberate
emission is greppable and carries a written reason.

THERE ARE NO PATH ALLOW-LISTS ANYWHERE IN THIS CHECK.  The only path decision
it makes is which files are shell at all.  A corpus case pins that moving an
exempt line into a different file does not change its verdict.

=========================================================================
WHAT COUNTS AS OUTPUT, AND WHAT COUNTS AS CAPTURE
=========================================================================

  * `echo` / `printf` at a command position.  Command words are matched by
    BASENAME, so `/bin/echo` and `./1/echo` are the same emitter.  A shell
    reserved word is not the command -- the command follows it -- so
    `if echo "$PAT"; then` is the same emitter.  A leading redirection and an
    option-bearing wrapper (`env -i echo ...`) are stepped over -- its
    OPTIONS only, so a wrapper carrying an operand or an option ARGUMENT
    (`timeout 5 echo ...`, `nice -n 5 echo ...`) resolves to that word instead
    and the emitter behind it is missed.  A redirection GLUED to the command
    word is the word plus an operator, not one token: `printf>&2 '%s' "$PAT"`
    runs printf with stdout on stderr, and only an IO_NUMBER (`2>&1`) or a
    `{name}` descriptor variable (`{fd}>&2`) stays part of the redirection.
    The `{name}` half of that sentence was PROSE ONLY until #1032 round 3:
    the lexer opened a brace GROUP at every word-initial `{`, so
    `{fd}>&2 printf '%s' "$PAT"` resolved its command word to `fd}` and the
    emitter behind it was never seen, while bash allocates a descriptor and
    prints the value.  `{` is a RESERVED WORD, and a reserved word is only
    that when it is a COMPLETE TOKEN, so the same reading also lost
    `echo {x,y} "$PAT"` -- a brace EXPANSION, an ordinary word -- to a
    command word of `x,y}`.  One rule now covers both.  And ALLOCATES is the
    operative verb: a `{name}` redirection does not move fd 1, so it is not a
    stdout move and cannot escape a capture or a pipe either.  Every one of
    those readings is a corpus case.
    An escaped command word (`\echo`) is the same emitter. `printf -v NAME`
    and `printf -vNAME` assign only in option position before the format and
    before `--`; the same spellings after the format are data and emit.
    The attached exemption is the owner-ratified Option A allowlist (#1645):
    target `[a-z_][a-z0-9_]*`, excluding `_`, `auto_resume` and `histchars`;
    a literal format with only unmodified `%s` conversions and plain text;
    values that are literal data or one double-quoted plain ordinary-name
    expansion, without modifiers, subscripts or arithmetic; and a bare command
    segment with no assignment prefixes, redirections or wrappers. The existing
    in-file builtin-provenance predicate must also pass. Every other attached
    form retains its conservative verdict, with safe false positives declared.
    Repeated assignment options and `--` precede the actual format. Separate
    `-v NAME`, including #1461 numeric diagnostics, keeps its prior scope.
    Imported printf functions are an owner-accepted residual: this source-only
    predicate cannot establish ambient lookup, so a function imported by Bash
    can print allowed assignment arguments. The noninteractive oracle also
    cannot settle terminal-only output. These are explicit limits, not promises
    of environment or shell-state proof. Captured arithmetic diagnostics (#2058),
    invalid-name indirection (#2059), and separate positional/array diagnostics
    (#2061) retain their measured existing limits. The quoted nonordinary-target
    reader remains bounded and refuses new clean verdicts; no general deferred
    operand-flow or function-invocation model is introduced.
  * An in-file message helper: a function whose body writes one of its own
    positional parameters VERBATIM through an emitter, or hands one to
    `cat`/`tee` on a HERE-STRING -- unless the file redefines that name, in
    which case the here-string goes to the local function and what a function
    does with its standard input is the declared limit below.  Both definition
    forms count, with brace or subshell bodies on the same or following line,
    including after inline or intervening comments. Quoted data and actual
    comments are excluded using existing lexer context, remapped from child
    substitutions; interpolating here-doc substitutions retain their executable
    source while their surrounding and nested here-doc data stay masked.
    Body extraction is
    compound-depth counted over lexer state, so a nested block whose
    closing brace starts its own line does not end it early.  Discovery
    retains EVERY recognized body for each name and iterates to a FIXED
    POINT over all of them, so any emitting body promotes the name and a
    helper reaching it through other helpers is found regardless of definition
    order or chain length. Textual definitions are not proof of execution;
    a later or false-branch emitter can conservatively flag a safe runtime
    call. No control-flow or runtime function table is inferred.
    Helper arguments, error words and interpolating here-doc bodies share
    the positional-value decision, with here-doc quotes literal and backslash
    quoting only dollar, backtick, backslash and newline. Quoted delimiters
    suppress body expansion. Actual backtick substitution bodies remove their
    source escape layer before the ordinary positional decision; modern
    substitutions retain ordinary source. Actual substitution source uses the
    existing literal deferred-operand extractor within its one-hop budget.
    Direct here-doc DATA retains conservative known-stdin-consumer admission.
    Quiet cat/tee shadow and command-report forms remain conservative (#1052
    item 3): textual declarations cannot prove active bindings. A catalog veto
    misses late, false-branch and restored-builtin emission, so no runtime
    definition/order/mutation model is added here.
    Continued openers are normalized before independent expansion/error-word
    searches; modern and legacy positional arithmetic and substring/index
    operands are retained as diagnostic candidates without evaluation. When the existing exact
    reader refuses a real command substitution's end, the remaining bounded
    source is retained conservatively, including possible inert tail data.
    No case grammar or runtime variable binding is inferred. Executable substitution
    and error-word evidence remains independent of that owner. Helper inventory
    stays conservative about captured/no-output source and does not infer
    runtime emission. A helper is
    graded on what its body writes, not on where that write GOES, so a helper
    whose emitter feeds a pipe is treated as emitting -- declared conservatism
    below.
  * The body of an INTERPOLATING here-doc (unquoted delimiter) owned by `cat`,
    `tee` or an emitter.  ALL here-doc openers on a line are tracked, not just
    the first (#1014), and the owner is the command of the SEGMENT the opener
    appears in, so `true; cat <<EOF` attributes the body to `cat`.  The
    delimiter is a WORD and ends at a shell METACHARACTER, so `<<E@F` names
    `E@F`.  A `$( )` inside the body is not text: it RUNS, and it is graded as
    a capture under the owner, so a redirection inside it escapes exactly as it
    does on an ordinary line.  Quoting is performed on the DELIMITER, never
    inside the body, so a `'` in the body is a literal apostrophe and
    suppresses nothing: `'$(printf '%s' "$PAT" >&2)'` between two of them
    still runs and still escapes.  Reading the body under ordinary
    single-quote semantics made exactly that a silent false negative.  A
    here-doc whose delimiter never arrives is REPORTED -- the scanner has lost
    sync with the file, and the remainder must not vanish into a body in
    silence.
  * The word of a here-STRING given to one of those same commands.
  * The LITERAL operand of `trap` or `eval`, re-read AS SHELL.  The operand is
    source the shell runs later, so quoting inside it quotes the TEXT and not
    an expansion: `trap 'echo "$PAT"' EXIT` prints the credential when the
    trap fires.  This is the same relationship an interpolating here-doc body
    has with its opener and it is handled the same way -- one hop
    (`_DEFERRED_SHELL_DEPTH`), and a discovery error inside the deferred text
    is REPORTED rather than dropped, for the reason an unterminated here-doc
    is. Known or conservatively retained active tracing at the enclosing
    segment initializes the literal operand scan. Inner disables receive only
    the existing standalone top-level disable credit; untraced references and
    references after a credited disable gain no xtrace finding from this
    bridge. Existing output-path analysis and command-boundary conservatism
    still apply. Already-retained deferred enables also reach later segments
    on the same logical line within the existing lexer parent scopes. Function
    invocation, trap timing and callback input availability are not inferred;
    safe sampled cases remain declared conservatism. Deferred initialization
    restores effective parent state after isolated shells; the ordinary
    reference state walk retains its prior scope. This is not call-time
    analysis of earlier
    function/trap definitions, and separately scanned sourced files do not
    inherit the caller state. An operand that does not reduce to a literal
    is not re-read; `trap`
    is opaque, so a reference the lexer can see inside one is flagged anyway.
    A `mapfile -C CALLBACK` / `readarray -C CALLBACK` argument is the same
    thing in a NAMED OPTION -- bash evaluates the callback -- and is re-read
    the same way, including bundled short options such as `-tC`. Only the
    effective final callback is selected for a proven literal option sequence;
    unknown prefixes or values retain the prior known-callback fallback. The
    literal callback operand is source: the search stops at `--` or the array
    operand and skips values consumed by other short options (#1450). An
    unresolved prefix cannot prove those boundaries, so later known callback
    operands remain conservative evidence without option dataflow.
  * A reference anywhere XTRACE is in effect.  With `set -x` (or `set -o
    xtrace`, bundled `set -eo/-euo xtrace`, `shopt -s -o/-os xtrace`,
    or a `-x` shebang) bash writes every EXPANDED command to stderr,
    so `: "$PAT"` -- the safest command word there is -- puts the value on a
    stream.  This is shell STATE, tracked in source order across the file and
    resolved per SEGMENT, so `( set -x; : "$PAT" )` counts and `set +x`,
    `set +o xtrace` and `set -- -x` are all read correctly.  The
    shared segment detector also reads immediate deferred enablement. Named
    operands after either sign of `o` retain their option boundaries; an
    unresolved word in the active set option stream may itself enable
    tracing or stop/abort parsing. It retains possible enablement through a
    later positional boundary and withholds subsequent disable credit in
    that command, without evaluating runtime values. Literal positional
    boundaries before that word still stop processing; missing `-o`/`+o`
    operands remain queries. A lone shopt dash begins its option-name list,
    including any later xtrace name.
    An unresolved shopt word can supply missing enable flags or option
    names; sampled non-enabling values are declared conservative. Named
    set options before invalid trailing letters retain their written enable
    evidence. Exact/bundled named operands share a finite literal-name proof
    before later disable credit; +ox and +xo preserve their option order.
    This does not infer errexit or general error-path execution, and keeps
    the legacy short-x conservative claim. Shopt query/disable modes and
    bundled `+o` gain no new disable credit.
    The directions are ASYMMETRIC on purpose: enabling is believed wherever it is
    written, disabling only from a line that is the whole `set` and is not
    inside a function body.  Crediting a `set +x` bash never runs is a silent
    false negative and is trivially reachable -- `set -x; f() { set +x; }` --
    while refusing a real one costs a visible finding a pragma settles.
  * A credential NAME split by a LINE CONTINUATION.  Bash removes
    `\\<newline>` before it parses the expansion, so `$GH_\\<newline>TOKEN`
    names GH_TOKEN and prints its value; matching the raw text stopped at the
    backslash and saw an unknown prefix.  `ident_at` is the single
    continuation-aware matcher, shared by the lexer, `braced_ref_at` and the
    here-doc body scanner, for the same reason `braced_ref_at` is shared.
  * A command word that is an ALIAS for an emitter, when `shopt -s
    expand_aliases` is on.  Alias names are folded into the emitter-helper
    set -- an alias is the relationship a helper already has with its call
    sites -- with bash's own two gates kept: `expand_aliases` must be
    enabled, and only a LITERAL target counts.
  * The ERROR WORD of a `${VAR:?word}` / `${VAR?word}` expansion.  BASH
    ITSELF writes that word to stderr when VAR is unset, before the enclosing
    command runs and whatever that command is, so `: "${UNSET:?$PAT}"` and
    `x=${UNSET:?$PAT}` both print the credential.  Grading it against the
    command word answered the wrong question.  The neighbouring operators
    (`:-`, `:=`, `:+`) substitute rather than write and are MUST_NOT_FLAG
    cases; the cost is that a SET variable never reaches its error word and
    the rule cannot know that, which is a declared conservatism.
  * The operand of a builtin that requires a NUMBER and REPRODUCES a
    non-numeric one in its own stderr diagnostic -- `exit`, `return`, `shift`,
    `break`, `continue`, `ulimit`, `wait`, `history`, `kill`.  Membership is
    oracle-decided; the near neighbours that stay silent (`let`, `umask`,
    positional `read`, `getopts`, `fc`) are MUST_NOT_FLAG cases.  Numeric
    option operands of `read` / `mapfile` / `readarray` and numeric operands
    of `test` / `[` take the same rule through their parsed positions.  A
    `read -p` operand is also output when stdin is a terminal.  The BOUNDARY
    is the operand's TYPE, not the fact of a diagnostic: `type`, `cd`, `hash`,
    `alias`, `pushd`, `dirs`, `shopt` and the external `ls`, `cat`, `rm`,
    `git`, `grep` all reproduce a bad operand too, and all of them take a NAME
    or a PATH whose validity is run-time state.  Those are
    `indirect-external-command`, the limit declared from the start, and three
    of them are pinned as corpus cases so the boundary is measured rather than
    asserted.  These write STDERR and
    the shields are built around stdout emitters, so the capture and pipeline
    spellings disagree with the oracle in both directions and all three are
    declared -- the descriptor seam is #1042's.
  * A command word the shell REWRITES before it names a command fails closed.
    `ec{h,}o "$PAT"` brace-expands to `echo` and `/bin/e[c]ho "$PAT"`
    pathname-expands to `/bin/echo`; both print the credential, and reading
    the unexpanded literal as the command matched no emitter.  The test is
    narrow enough that `[ -n "$PAT" ]`, `[[ ... ]]`, `{ ...; }` and a quoted
    `"ec{h,}o"` are untouched, and the cost -- an expansion that resolves to a
    NON-emitting command reds anyway -- is a declared conservatism.

A PIPELINE IS NOT AN EMISSION; ITS CONSUMER DECIDES.  `printf '%s' "$PAT" |`
puts the value on the next command's STANDARD INPUT, which is the same act as
a here-doc body and a here-string -- and `grep -qF x <<< "$PAT"` is already
clean.  So the walk follows the pipe and asks what the consumer does with its
stdin: `cat`/`tee` write it (flagged, and a `cat | cat | grep -q` chain is
followed hop by hop), an unresolvable or `eval` consumer fails closed, and
anything else is the same unmodelled question as a value handed to a command
as an ARGUMENT.  This is what makes `printf '%s' "$PAT" | gh auth login
--with-token` and `echo "$PAT" | docker login --password-stdin` -- the
canonical secure hand-off, and gh's and docker's own documented interface --
legal without a pragma.  Only a redirection that moves fd 1 escapes the pipe
(`>&2`, `>file`); `2>/dev/null` and `0>/dev/null` do not.  A trailing `|`
continues the command list onto the next physical line, exactly as a trailing
`\` does.

A `tee` in the middle of the pipeline is the one hop that is not transparent:
`tee FILE` writes the file AND passes the value on, so the write is counted
under the same rule as `printf '%s' "$PAT" > log` even though the pipeline
carries the value onward to a consumer that discards it.  Only a LITERAL
operand counts, and `/dev/null` does not: `tee "$LOG"` names a path the source
text does not fix, and flagging it would red the ordinary logging idiom across
the fleet.  That residue is a declared miss, pinned by a corpus case, not an
oversight.

CAPTURE IS NOT EMISSION.  In `_v=$(printf '%s' "$GH_TOKEN")` the value goes
into a variable.  The shield is conditional, because #1012 measured the escape:
`_v=$(printf '%s' "$GH_TOKEN" >&2)` redirects past the capture and reaches the
terminal.  So a captured emitter counts as capture only when NO output
redirection stands between the emitter and the capture; any output redirection
the value passes through on its way out of the substitution is flagged.

A subshell does not capture anything ITSELF -- `( echo "$PAT" )` at the top
level is flagged -- but its standard output goes wherever the ENCLOSING
COMMAND's does, so the walk out of one is TRANSPARENT: it lands on the segment
the `( )` was written in and reads that segment's redirection, pipe and
capture, because those are the subshell's own.  Written inside `$( )` a
subshell is therefore shielded exactly as a bare command is, and every
spelling of the escape is flagged exactly as the bare one is -- `>&2` written
inside the parens, after the `)`, or on a `( )` nested one level in.  Piped,
it is graded by its CONSUMER, again exactly as a bare emitter is:
`( printf '%s' "$PAT" ) | gh auth login --with-token` is legal.  Reading the
relationship as "captured BY the enclosing segment" instead of "inside a
subshell written in it" made the parens change the answer, in both directions
at once -- the redirection after the `)` went unread while the same construct
under an array assignment's `$( )` was flagged with no capture at all
(#1032 round 2).

An array assignment's parenthesised list is data, and a `$( )` among its
elements is a capture under that assignment.

REDACTION IS NOT EMISSION.  `${#VAR}` is a length and `${VAR:+set}` is a
constant alternate; neither is a value reference, so both are legal with no
pragma -- they are the #993 remediation and adopting it never trips the gate.
`${VAR:+$VAR}` carries its own expansion and the inner reference is flagged on
its own.  A helper that derives a length or a class and prints that is
therefore not a message helper, so `key_state "$PAT"` stays legal.

=========================================================================
WHAT THIS CHECK DOES NOT CATCH
=========================================================================

Re-derived from what the harness ACTUALLY shows, not from what the author
believes.  Every entry below that names a shell CONSTRUCT is a live corpus case
whose disagreement with the oracle is declared in `KNOWN_MISSES`, and
`--self-test` PRINTS that registry on every run, so this prose cannot drift
away from the measurement -- if the two ever disagree, the printed list is the
true one.  Two entries are NOT constructs and carry no corpus case, and both
say so where they appear: what the shell emits on its own (`set -x`, core
dumps), and files this check does not read at all.  Two more ARE constructs
with live corpus cases that nonetheless carry no `KNOWN_MISSES` entry, because
the oracle AGREES with the scanner about them -- a `tee` whose operand is not
literal, and a file that redefines `cat`/`tee`.  Ground truth here is what
reaches a STREAM, and both of those limits are about a value reaching a FILE or
a local function, which the oracle has no verdict on; the case pins the
scanner's answer, and the reason it is the chosen answer is written here.  Read
the other direction
too, and it holds with one exception: every `KNOWN_MISSES` entry appears below
except `pragma-honoured`, which is not a limit -- it is the deliberate
exemption described above, a declared "miss" because the line really does emit
and the scanner really does stay silent, on purpose.

READ IT AS THE MEASURED SAMPLE IT IS: an absence from this list is NOT
coverage.  The scanner is a source-text approximation; the oracle is the only
thing here that knows the truth, and it only knows it about constructs someone
put in the corpus -- and only under the one sentinel shape that corpus samples
(#1036, and the oracle paragraph above).

The list below mixes TWO KINDS of gap and says which is which.  Most of it is
the DESIGN LIMIT: this is a single-hop source-text scanner over one logical line
at a time, with no dataflow, no cross-file analysis, and no knowledge of what a
variable holds at runtime, so indirection, external commands, interpreters and
unscanned files are permanently out of reach.  Two bullets are marked (#1035)
instead: those are `resolve_command` / `classify` mis-deciding what a segment
RUNS, a repairable seam with an open issue, not a property of the design.  It
does not catch:

  * A token copied into a differently-named variable and then printed
    (`pat=$OP_PREFLIGHT_AUTHOR_PAT; echo "$pat"`), or reached through a
    function return, a `read`, a `printf -v`, a loop variable, or `$(op read
    ...)`.
  * A token written to a log or temp file that some later line prints
    (`cat "$LOG"`).  It DOES catch the line that puts the value into the log,
    when that line names the variable; it cannot connect that line to the `cat`
    that prints it.
  * Core dumps or other shell/runtime output whose triggering value is not a
    credential reference the scanner can see.  Xtrace is NOT in this gap:
    `set -x`, `set -o xtrace`, xtrace shebangs and deferred code that enables
    tracing are live corpus cases and are tracked as shell state below.
  * (#1035) A SHELL-STATE DUMPER on a segment that names no credential
    variable.  The boundary here is the REFERENCE, not the command word, and
    the earlier wording of this bullet had it the other way round.  This scanner asks
    "does this reference reach a stream?", so `classify()` -- which is where
    `env`/`printenv`/`set`/`compgen` are known to be dumpers at all -- is
    consulted only for a segment carrying a `$`-reference.  Measured, on this
    head: `set`, `set -o posix; set`, `declare -p GH_TOKEN` and
    `export GH_TOKEN; env` each put the value on a stream and each reads
    CLEAN, and all four are live corpus cases in `KNOWN_MISSES`.  What IS
    caught is `FOO="$GH_TOKEN" env` and `env FOO="$GH_TOKEN"` -- both corpus
    cases, both measured true positives -- and they are caught because the
    segment carries a reference, which is what makes the walk run and then ask
    whether the command dumps the environment it was handed.  A dumper reached
    through a variable is not caught either, because nothing in the source text
    says what it is.
  * (#1035) A WRAPPER whose real command word sits behind an operand or an
    option ARGUMENT: `timeout 5 echo "$PAT"` and `nice -n 5 echo "$PAT"` both
    resolve to `5` and read clean.  Wrapper OPTIONS are stepped over; wrapper
    operands are not parsed.
  * A token handed to an EXTERNAL command -- as an ARGUMENT
    (`curl -H "Authorization: Bearer $CF_API_TOKEN"`), on a HERE-STRING
    (`grep . <<< "$PAT"`), or through a PIPE (`printf '%s' "$PAT" | grep .`).
    This check knows what `echo`, `printf`, `cat` and `tee` do with what they
    are handed and does not pretend to know what anything else does.
    Deliberate: flagging every external command that receives a credential
    would red a required fleet-wide check on the ordinary way credentials are
    passed.  All three spellings carry the same verdict on purpose -- flagging
    only the pipe one made the gate contradict itself, and it reds the
    canonical `--with-token` / `--password-stdin` hand-off.
  * A quote-bearing comment adjacent to a `name()` header without whitespace,
    as in `helper-adjacent-comment-unmatched-quotes`. The existing declaration
    word in the Lexer prevents that `#` from starting a comment, so its quotes
    can hide the later call. Function-body discovery recognizes the real
    definition; this prior-main tokenization gap remains tracked by #2080
    (https://github.com/nathanjohnpayne/mergepath/issues/2080).
  * An in-file helper that writes its STANDARD INPUT rather than one of its
    positional parameters (`relay() { cat; }` behind a pipe).  Helper
    discovery models parameters; nothing at the call site says what a helper
    reads.  A file that redefines `cat` or `tee` reaches the same limit from
    the other side, and helper discovery stops treating the name as a
    stdin-writer rather than guessing at the replacement.
  * A `tee` whose file operand is not LITERAL (`... | tee "$LOG" | grep -q x`).
    The file write is what makes a mid-pipeline `tee` visible at all, and the
    operand is the only thing in the source text that names the file.
    Deliberate: reading every non-literal operand as a write would red the
    ordinary logging idiom on a required fleet-wide check.
  * A token reaching an interpreter through SOURCE TEXT that then prints it
    (`bash -c ...`, `python3 -c ...`, `awk -v ...`, a `bash <<EOF` here-doc).
    A literal shell SCRIPT operand is different: `bash scripts/leak.py`
    promotes `leak.py` into discovery and scans it as shell whatever its name.
  * Any file this check does not scan: everything outside scripts/** and
    tests/**, and a non-shell file inside them that no scanned shell file
    SOURCES or invokes through a shell interpreter by a LITERAL operand.  A
    sourced/invoked fragment IS read whatever it is called, but the operand is
    resolved, never the candidate's contents, so `. "$LIB/x.env"` and
    `bash "$SCRIPT"` leave that fragment unread.  Deciding by contents would
    mean deciding which `.env`/`.py` files are shell, on a check that publishes
    the required `lint` context for nine repositories.  Also not a construct:
    the file-selection axis pins WHICH files are read, not what a leak inside
    an unread one looks like, so there is no CORPUS case behind this one -- the
    assertions live in `_shell_file_promotion_cases`, which measures the
    executing script under bash end to end.

CONSERVATISM RUNS THE OTHER WAY IN A SHORT LIST, also measured, and
`KNOWN_BROADER` -- printed on every `--self-test` run -- is the authoritative
copy of it; this prose is a description of that registry, not a second source:

  * An emitter redirected to a FILE (`printf '%s\n' "$PAT" > log`) puts
    nothing on a stream, and the gate flags it anyway.  That write is the
    FIRST HOP of the check_resolve_pr_threads leak #993 fixed, and the gate is
    built so that hop stays visible.  Four shapes land on this same rule and
    are declared separately because they arrive by different routes: a
    redirection glued to the command word (`printf&>out.txt ...`); a
    mid-pipeline `tee FILE`, which forks the value into a file while the
    pipeline carries it on to a consumer that discards it; and a message
    HELPER whose emitter is redirected to a file
    (`log() { cat <<< "$1" > out.txt; }`), which helper discovery grades on
    what the body WRITES without asking where the write goes.
  * A helper name with ANY recognized emitting definition is classified as
    emitting, even when that definition occurs after the call, in an unexecuted
    branch, or before a safe redefinition that actually executes (#1467).
    The fixed point retains all bodies, including inner/outer redefinitions;
    textual order and branch conditions do not establish runtime lookup.
  * A pipeline whose consumer is NOT a simple command -- `| { read -r v; }`,
    `| ( read -r v )`, and `|&`, whose consumer segment is recorded empty.
    Which command inside a group reads the pipe is a dataflow question a
    single-line source-text scanner cannot answer, so the consumer counts as
    unresolved and the case fails CLOSED.  The named-command form of the same
    idiom (`| gh auth login --with-token`) is clean.
  * (#1042) A redirection inside `$( )` that moves a descriptor OTHER than
    fd 1: `v=$(printf '%s' "$PAT" 2>/dev/null)` and `v=$(... 2>&1)` reach no
    stream, and the capture hop counts any output redirection rather than
    only one that moves fd 1 -- while the PIPELINE hop of the same function
    already asks the fd-aware question.  `v=$( ( ... ) 2>/dev/null )` is the
    third spelling and is deliberately graded by that same reading: one wrong
    answer #1042 corrects in one place beats two spellings of a line
    disagreeing.  All three entries go stale together when #1042 lands.
  * (#1035) A MESSAGE HELPER whose emitter feeds a pipe:
    `login() { printf %s "$1" | gh auth login --with-token; }` plus
    `login "$PAT"`.  Helper discovery grades what the body writes without
    asking where that write goes, so it does not run the pipeline-consumer
    analysis the direct form gets.  Nothing reaches a stream and the gate reds.
  * (#1035) An INPUT PROCESS SUBSTITUTION: `grep -qF x <(printf '%s'
    "$PAT")`.  Every `<(...)` body is graded as a standalone output path with
    no model of what consumes the fd, so this reds while emitting nothing.  `cat <(...)` really
    does leak and is flagged by the same undiscriminating rule, which is why
    the two are not currently told apart.

The last two are LIVE false positives on a check that publishes the required
`lint` context, not conservatism anyone chose; both are declared in
`KNOWN_BROADER` and both are #1035's to repair.  Neither fires on any of the
ten trees measured today.  Until the repair lands, A FALSE POSITIVE IS
ESCAPABLE AT THE SITE: add `# TOKEN_OUTPUT_EXEMPT: <reason>` to the line, with
a reason (the reason is mandatory).  That is the same inline pragma a
legitimate emitter uses, it needs no change to this file and no path
allow-list, and it leaves the decision greppable.

STATED PLAINLY, because #993's lesson was that an unstated limit reads as a
guarantee: NONE of the three leaks #993 fixed would have been caught by this
gate at their original sites.  All three reached the token under another name
or through a file.  This gate stops the DIRECT form from coming back; it is
not a proof that no credential can reach a stream.

And the recall claim is bounded by the CORPUS and by the SENTINEL, not by an
argument.  What the harness demonstrates is that on ~440 constructs --
generated across line spellings, file selection, pipeline consumers and
legal-but-unusual precision shapes, each measured against ONE letter-leading
sentinel value and only down to a four-character fragment -- the scanner and
bash agree except for the declared entries.  The run prints the exact count,
the interpreter, the sentinel shape AND the detection floor that produced it,
and both registries; that print is the number of record, not this sentence.  A
construct nobody wrote into the corpus is not covered by the statement at all,
neither is a value shape nobody sampled (#1036), and neither is a leak too
short for the floor.  Adding
a construct is a three-line edit to `CORPUS`, and the oracle decides it --
under an interpreter that can evaluate it, which is what `ORACLE_BASH_MIN`
is for.

Related and equally out of reach (#1021): `scripts/op-preflight.sh` writing
export lines carrying live PAT values to ITS OWN stdout is a CALLER-side
problem.  That emission is the script's contract when its output is consumed by
`eval`, and a leak when a caller lets it reach a transcript.  No source-text
rule over `scripts/**` can separate the two, because the difference is in the
caller, not in the line.  The three op-preflight emitters carry
`TOKEN_OUTPUT_EXEMPT` pragmas so the decision is greppable; that is all a
source-text gate can do here.

=========================================================================
FILE DISCOVERY FAILS CLOSED
=========================================================================

#1012 shipped a discovery that failed OPEN: `#!/usr/bin/env -S bash -e` on an
extensionless script reduced the interpreter to `-S`, so the file was not
recognised as shell at all and a tree whose only file was such a script,
containing a live `echo "$GH_TOKEN"`, reported `scanned 0 shell files` and
PASS.  That is the #951 shape -- a green gate saying nothing was wrong --
reproduced inside the gate built to stop #951.

Here the property asserted is: A FILE BASH WILL EXECUTE IS A FILE THE GATE
READS, and every branch that cannot establish it is FATAL, not skipped:

  * A shebang is resolved through `env`, including `-S` / `--split-string=`,
    `-i`, `-u NAME`, `-C DIR` and `NAME=VALUE` assignments.
  * A file whose interpreter or extension classifies as neither shell nor
    known-non-shell is READ AS SHELL, not skipped.  The asymmetry is
    deliberate and written out at `classify_file`: scanning a non-shell text
    file costs at most a visible finding a pragma or a rename settles, and
    skipping a shell file costs a silent PASS.  (This bullet said "is an
    ERROR" until #1032 round 3 and the code never did that -- the two
    unclassifiable-file cases have asserted the READ since the file was
    written.)
  * A file a scanned shell file SOURCES by a literal operand is SHELL, whatever
    the extension table said: `. ./lib.env` runs `lib.env` in the sourcing
    shell, so a leak inside it is a leak in the sourcing script.  Resolved to
    a fixed point, because a promoted fragment can source another.  ONE
    leading `--` is the builtin's option terminator and is stepped over --
    taking the first word after `source` unconditionally recorded `--` as the
    operand, so `source -- ./lib.env` left the fragment unread while bash
    executed it.  The SECOND `--` is the filename, which is what bash does;
    both readings are measured end to end.
  * An unreadable path, or a traversal failure, is an ERROR.  That includes an
    unreadable DIRECTORY, which `os.walk` otherwise swallows: without an
    `onerror` callback the subtree yields nothing, the walk continues, and the
    zero-file guard never fires because the sibling files still make the count
    non-zero.  A green gate over a subtree it could not read is the #951 shape
    one level down.
  * A scan ROOT that exists and is not a directory is an ERROR.  A regular
    file, a device or a dangling symlink named `scripts` all read as False to
    `os.path.isdir`, which the walk took for "root absent" and skipped -- and
    the SIBLING root kept both the root count and the file count non-zero, so
    neither guard below could fire.  A PASS over a tree whose `scripts/**`
    was never walked is the same silent shrink as the unreadable directory
    above.
  * A scan selecting ZERO shell files is an ERROR.  `scanned 0` can never be
    an advisory count on a PASS line again; a corpus case asserts it directly.
  * A here-doc whose delimiter never arrives is an ERROR.  It is the same
    silent shrink INSIDE a file: every line after the opener is read as body
    text rather than as code, and the scanner reports the loss of sync rather
    than returning a clean verdict over source it never parsed.  The
    assertion behind it uses a LEAK-FREE body on purpose: the corpus case
    `heredoc-unterminated` names a credential in its body, so it flags
    through the FINDING and survives the error being deleted -- a property
    asserted in prose with nothing pinning it is the failure mode this file
    exists to end (#1032 round 3 M1).

Every bullet above is asserted: the shebang one in `_shebang_cases` and
`_file_selection_cases`, the source-promotion one in
`_shell_file_promotion_cases`, the rest in `_discovery_failure_cases`.  Each
assertion added in #1032 round 3 was checked by DELETING the branch it covers
and confirming the suite goes red.

Usage:
    check_no_token_in_output              # self-test, then scan this repo
    check_no_token_in_output --self-test  # oracle-differential suite only
    check_no_token_in_output --scan [DIR] # scan only (default: this repo)

`--scan DIR` is also how the fleet measurement is taken: pointing it at
mergepath plus the nine consumer checkouts is the ten-tree hit-set comparison
#1015 asks for.  It is deliberately NOT a CI step -- CI has one tree, and a
step that cloned nine repositories to lint one would be a different kind of
gate.  The numbers from that run belong in the PR body, where a reviewer can
see them.

Exit codes: 0 pass, 1 findings or a failing case, 2 usage/environment error.
"""

from __future__ import annotations

import concurrent.futures
import os
import re
import shlex
import shutil
import stat
import subprocess
import sys
import tempfile

# --------------------------------------------------------------------------
# The closed credential-variable list.
#
# Every name here DENOTES credential material that this fleet either handles at
# runtime or asserts about in its own secret-hygiene fixtures.  Names that
# merely *mention* a credential (an Actions secret name in a string, a "which
# token should I use" flag) are deliberately absent -- see the header.
#
# The invariant reads "denotes credential material", not "is live here",
# because the first is a property of the NAME and the second is a property of
# today's integrations.  An earlier round of #1012 declined AZURE_CLIENT_SECRET
# on the "not live here" reading and was wrong on its own terms:
# tests/test_phase_4b_automation.sh drives the reviewer-adapter env allow-list
# with AZURE_CLIENT_SECRET set, so the fleet does assert about it.
#
# Four names from that same fixture stay absent, and not because anyone forgot:
# GOOGLE_APPLICATION_CREDENTIALS, OP_PREFLIGHT_ADC_TMPFILE and
# OP_PREFLIGHT_FIREBASE_SA_TMPFILE are FILE PATHS and SSH_AUTH_SOCK is a socket
# path -- printing one leaks no secret, and op-preflight.sh prints
# GOOGLE_APPLICATION_CREDENTIALS deliberately and without a pragma, so
# admitting it would red a required check over a legitimate line.
# AWS_ACCESS_KEY_ID is a public identifier and its paired secret appears
# nowhere in this fleet, so adding it would break the invariant the other way.
# --------------------------------------------------------------------------
TOKEN_NAMES = (
    "GH_TOKEN",
    "GITHUB_TOKEN",
    "GH_ENTERPRISE_TOKEN",
    "GITHUB_ENTERPRISE_TOKEN",
    "GH_RESOLVED_TOKEN",
    "OP_PREFLIGHT_AUTHOR_PAT",
    "OP_PREFLIGHT_REVIEWER_PAT",
    "OP_SERVICE_ACCOUNT_TOKEN",
    "AUTHOR_MERGE_TOKEN",
    "REVIEWER_ASSIGNMENT_TOKEN",
    "BRANCH_PROTECTION_AUDIT_TOKEN",
    "LABEL_REMOVAL_TOKEN",
    "CF_API_TOKEN",
    "CLOUDFLARE_API_TOKEN",
    "FIREBASE_TOKEN",
    "AZURE_CLIENT_SECRET",
    "ANTHROPIC_AUTH_TOKEN",
    "CLAUDE_CODE_OAUTH_TOKEN",
    "OPENAI_API_KEY",
    "CODEX_API_KEY",
    "ANTHROPIC_API_KEY",
)
TOKEN_NAME_SET = frozenset(TOKEN_NAMES)

# Names that a TOKEN / PAT / SECRET heuristic would fire on in this tree and
# that hold no credential material.  Pinned by a corpus case in the clean
# direction: admitting any of them to TOKEN_NAMES kills that case.
NON_CREDENTIAL_LOOKALIKES = (
    "SUMMARY_ACK_TOKEN",
    "ACK_TOKEN",
    "MERGEPATH_EXPECT_READ_GH_TOKEN",
    "STEP_NO_TOKEN",
    "BOOTSTRAP_SKIP_AUTHOR_TOKEN",
)

PRAGMA = "TOKEN_OUTPUT_EXEMPT"

SCAN_ROOTS = ("scripts", "tests")

EMITTERS = frozenset({"echo", "printf"})
# Commands that write their standard input, so a here-doc body or here-string
# handed to one reaches a stream.
STDIN_ECHOERS = frozenset({"cat", "tee"})
# Commands that never write an argument to a stream.  Terminal: resolution
# stops here.
SAFE_COMMANDS = frozenset(
    {
        # conditionals and word-consuming keywords.  Numeric `test` / `[`
        # operands are decided before classification; the remaining positions
        # read the value and do not write it.
        "[", "[[", "test", "case", "for", "((",
        # binding forms
        "local", "export", "readonly", "declare", "typeset", "unset", "read",
        "let",
        # no-ops and control
        ":", "true", "false", "shift", "return", "exit",
    }
)
# Builtins that require a NUMERIC operand and, when handed a non-numeric one,
# REPRODUCE THAT OPERAND VERBATIM in their own diagnostic on stderr:
#
#     $ exit "$GH_TOKEN"
#     bash: exit: Zq7Xf2Lp9Vt4Rk8Nb3Md6Wc1Ys5Hj0Gr: numeric argument required
#
# So a credential in that position IS an output path, and classifying these
# universally safe made `--scan` report PASS on a live stderr leak (#1032
# round 4 P1).  The membership is oracle-DECIDED, not guessed: every builtin
# below was measured putting the sentinel on a stream, and the near neighbours
# that do NOT -- `let`, `umask`, positional `read`, `getopts`, `fc`, binding
# forms, and non-numeric conditional positions -- were measured clean and are
# deliberately absent, each pinned by a MUST_NOT_FLAG corpus case.  A
# credential-named operand is what fires this; `exit "$rc"` names no
# credential and is not a reference at all.
# OPTIONS that require a numeric operand.  The commands themselves stay out of
# NUMERIC_OPERAND_DIAGNOSTIC because their POSITIONAL operands are not all
# numeric: `read "$GH_TOKEN"` treats the value as a variable name, while
# `mapfile values` names an array.  The leak is in these option positions.
#
# These options take a timeout, count, origin, quantum or file descriptor, so
# a credential can never be a valid operand and bash reproduces it verbatim on
# stderr:
#
#     $ read -t "$GH_TOKEN" x </dev/null
#     bash: read: Zq7Xf2Lp9Vt4Rk8Nb3Md6Wc1Ys5Hj0Gr: invalid timeout specification
#
# So this is the `NUMERIC_OPERAND_DIAGNOSTIC` rule reached through an option
# rather than a command word, and it is decided by the same test -- the
# operand TYPE is numeric, so a credential is never valid and the diagnostic
# is certain.  Keep the option grammar in one table: `read` landed first and a
# command-specific parser left the identical `mapfile` / `readarray` path
# invisible (#1032 fresh Codex P1 after round 9).
NUMERIC_OPTION_LETTERS = {
    "read": frozenset({"t", "n", "N", "u"}),
    "mapfile": frozenset({"n", "O", "s", "c", "u"}),
    "readarray": frozenset({"n", "O", "s", "c", "u"}),
}
# Every short option that consumes an operand for the same builtins.  The
# scanner must step over non-target operands too: `read -d x -p "$PAT"` and
# `mapfile -d x -n "$PAT"` are valid, and stopping at `x` would hide the later
# output/numeric option.
SHORT_OPTION_OPERAND_LETTERS = {
    "read": frozenset({"a", "d", "i", "n", "N", "p", "t", "u"}),
    "mapfile": frozenset({"d", "n", "O", "s", "u", "C", "c"}),
    "readarray": frozenset({"d", "n", "O", "s", "u", "C", "c"}),
}
TEST_NUMERIC_OPERATORS = frozenset({"-eq", "-ne", "-lt", "-le", "-gt", "-ge"})
NUMERIC_OPERAND_DIAGNOSTIC = frozenset(
    {
        "exit", "return", "shift", "break", "continue", "ulimit", "wait",
        "history",
        # `kill` takes a PID or a jobspec, so a credential can never be a
        # valid operand and the diagnostic is as deterministic as the rest of
        # this set (#1032 round 5 P1).
        "kill",
    }
)
# The BOUNDARY of the set above, stated because it is the difference between a
# closed rule and an open enumeration.  Membership is "the operand's TYPE is
# numeric, so a credential can NEVER be valid and the diagnostic is certain".
# It is NOT "any command that reproduces a bad operand", because that is very
# nearly every command there is: `type`, `hash`, `cd`, `alias`, `pushd`,
# `dirs`, `shopt`, `bind`, `caller`, `enable`, `unalias`, `jobs`, `disown`
# all do it, and so do `ls`, `cat`, `rm`, `git` and `grep` -- all measured.
# Those take a NAME or a PATH, their diagnostic depends on what exists at run
# time, and they are the `indirect-external-command` limit this gate has
# declared from the start rather than a list waiting to be completed.
# `numeric-operand-boundary-*` are the corpus cases that keep the distinction
# measured instead of asserted.
# Commands that dump the environment they were given, so an env-prefix
# assignment feeding one does reach a stream.
ENV_DUMPERS = frozenset({"env", "printenv", "set", "compgen"})
# Wrappers whose real command word is further along the line.
PASSTHRU = frozenset(
    {
        "env", "command", "builtin", "exec", "nohup", "nice", "ionice",
        "stdbuf", "time", "timeout", "setsid", "unbuffer",
    }
)
# Command words that hand the whole word to a shell/interpreter.  Unresolvable
# by a source-text scanner, so they are fail-closed rather than assumed safe.
OPAQUE_COMMANDS = frozenset({"eval", "source", ".", "trap"})

RESERVED_WORDS = frozenset(
    {
        "if", "then", "elif", "else", "fi", "while", "until", "do", "done",
        "function", "!", "in", "coproc", "esac", "{", "}",
    }
)

SHELL_INTERPRETERS = frozenset(
    {"sh", "bash", "dash", "ksh", "ksh93", "mksh", "pdksh", "zsh", "ash", "yash"}
)
NON_SHELL_INTERPRETERS = frozenset(
    {
        "python", "python2", "python3", "node", "nodejs", "deno", "bun",
        "tsx", "ts-node", "ruby", "perl", "php", "awk", "gawk", "mawk",
        "sed", "Rscript", "osascript", "jq", "make", "expect", "tclsh",
        "lua", "groovy", "swift", "julia", "escript", "pwsh", "elixir",
        "false", "true",
    }
)
SHELL_EXTS = frozenset({".sh", ".bash", ".ksh", ".zsh", ".dash", ".bats"})
# Dialects DISCOVERY selects but the EMITTER MODEL cannot read.  `EMITTERS` is
# `{echo, printf}` and every other command word grades as an unknown external
# command, i.e. SAFE.  In zsh and ksh `print -r -- "$GH_TOKEN"` is a BUILTIN
# that writes the value to stdout, so a selected `.zsh` file leaked under a
# PASS -- measured (#1032 round 6 P1).
#
# The answer here is the NARROW one, and it is the same shape as
# `numeric-operand-boundary-*`: keep SELECTING these files, so a dialect this
# gate cannot grade can never become a file it silently skipped, and refuse to
# call the result CLEAN.  The bash model still runs over them -- it catches
# every construct the dialects share, which is most of them -- and a
# discovery ERROR is raised alongside, so the tree cannot report clean on a
# file whose output builtins are outside the model.
#
# Modelling `print` instead would open exactly the enumeration this gate has
# declined everywhere else: `print`, `printf`-alikes, `-` variants, and zsh
# and ksh each spell them differently.  Worse, none of it could be MEASURED --
# the oracle runs bash, and `zsh`/`ksh` are not on every runner (the
# file-selection axis already records that fallback), so each addition would
# be asserted rather than decided.  A refusal is decidable; a guess is not.
UNMODELLED_SHELL_DIALECTS = frozenset({"zsh", "ksh", "ksh93", "mksh", "pdksh"})
UNMODELLED_SHELL_EXTS = frozenset({".zsh", ".ksh"})
NON_SHELL_EXTS = frozenset(
    {
        ".md", ".markdown", ".json", ".jsonl", ".yml", ".yaml", ".txt", ".py",
        ".js", ".cjs", ".mjs", ".ts", ".tsx", ".jsx", ".png", ".jpg", ".jpeg",
        ".gif", ".svg", ".pdf", ".ico", ".lock", ".toml", ".ini", ".cfg",
        ".conf", ".xml", ".html", ".htm", ".css", ".csv", ".tsv", ".log",
        ".patch", ".diff", ".sample", ".gitignore", ".gitattributes", ".rb",
        ".go", ".rs", ".java", ".c", ".h", ".cpp", ".sql", ".env", ".ndjson",
        ".pem", ".crt", ".key", ".zip", ".tar", ".gz", ".jsonc", ".plist",
    }
)


class CheckError(Exception):
    """A condition that makes the scan's answer untrustworthy.  Always fatal."""


# ==========================================================================
# Lexer
# ==========================================================================
#
# One pass over the file produces, for every character: whether a `$` there
# would expand, whether it sits in a comment, and which command SEGMENT owns
# it.  Everything downstream reads off that; there is no second walk with its
# own idea of quoting, which is the divergence #1012's comment-finder and
# continuation-finder produced.

class Segment:
    __slots__ = (
        "sid", "parent", "parent_is_capture", "parent_is_subshell", "words",
        "line", "pipe_to", "_cmd", "_resolved", "_cmd_index", "_cmd_literal",
        "_function_binding",
    )

    def __init__(self, sid, parent, parent_is_capture, line):
        self.sid = sid
        self.parent = parent
        self.parent_is_capture = parent_is_capture
        # Set when this segment is one of the commands INSIDE a `( ... )`
        # subshell, in which case `parent` is the segment the subshell was
        # written in -- the segment that carries any redirection written
        # after the `)`, because that redirection is the subshell's own.
        #
        # It is a DIFFERENT relationship from `parent_is_capture`, and
        # conflating the two is what made `v=$( ( printf %s "$PAT" ) >&2 )`
        # read clean (#1032 round 2 F10): the walk graded the wrapper as if
        # the subshell's stdout had been captured BY it, so the `>&2` the
        # wrapper carries was never consulted.  A subshell captures
        # nothing; its standard output IS the enclosing command's, so the
        # hop out of one is transparent and the wrapper is asked only
        # where its own output goes.
        self.parent_is_subshell = False
        self.words = []  # list of (text, is_quoted_start)
        self.line = line
        # The segment this one's STDOUT is piped into, when a `|` separates
        # them.  A pipeline is the third spelling of "hand this value to a
        # command's standard input", after a here-doc body and a here-string,
        # and `reaches_output` walks all three the same way.
        self.pipe_to = None
        self._cmd = None
        self._resolved = False
        self._cmd_index = None
        self._cmd_literal = None
        self._function_binding = None


class Ref:
    __slots__ = (
        "name", "line", "seg", "heredoc_owner", "in_assign_prefix",
        "in_heredoc_body", "in_error_word",
    )

    def __init__(self, name, line, seg, in_assign_prefix=False):
        self.name = name
        self.line = line
        self.seg = seg
        # Set when the reference sits in the ERROR WORD of a `${VAR:?word}` /
        # `${VAR?word}` expansion.  THE EXPANSION writes that word to stderr
        # itself, before the enclosing command runs and whatever that command
        # is, so the reference reaches a stream even under `:` or a bare
        # assignment -- `x=${UNSET:?$PAT}` prints the credential and exits.
        # Grading it against the command word answered a question that is not
        # the one being asked (#1032 round 5 P1).
        self.in_error_word = False
        # Set when the reference is body TEXT the here-doc owner writes, so
        # the owner's segment is where the walk starts.  A reference inside a
        # COMMAND SUBSTITUTION in that same body leaves this None and carries
        # `in_heredoc_body` instead: its own segment runs first, and the body
        # is only where its output lands.
        self.heredoc_owner = None
        self.in_assign_prefix = in_assign_prefix
        self.in_heredoc_body = False


class HereDoc:
    __slots__ = ("delim", "interpolating", "strip_tabs", "owner", "body_lines")

    def __init__(self, delim, interpolating, strip_tabs, owner):
        self.delim = delim
        self.interpolating = interpolating
        self.strip_tabs = strip_tabs
        self.owner = owner
        self.body_lines = []


class LogicalLine:
    __slots__ = ("first_line", "segments", "refs", "pragma_reasons", "pragma_bare")

    def __init__(self, first_line):
        self.first_line = first_line
        self.segments = []
        self.refs = []
        self.pragma_reasons = []
        self.pragma_bare = False


_WORD_BREAK_BEFORE_COMMENT = set(" \t\n;&|()")
_IDENT_RE = re.compile(r"[A-Za-z_][A-Za-z0-9_]*")
_ASSIGN_RE = re.compile(r"^[A-Za-z_][A-Za-z0-9_]*(\[[^]]*\])?\+?=")
# The ONLY things bash lets precede a redirection operator inside the same
# token are an IO_NUMBER (`2>&1`) and a `{name}` descriptor variable.  Ordinary
# word characters do NOT glue: `printf>&2 '%s' "$PAT"` is the WORD `printf`
# followed by the redirection `>&2`, and bash runs printf with its stdout on
# stderr.  Accepting `[A-Za-z0-9_]*` here read that whole thing as one
# redirection-only token, so the emitter was never seen and the leak passed
# (#1032 F1).  The lexer now breaks the word at the operator, which is what
# makes these anchors correct rather than merely narrower.
_FD_PREFIX = r"(?:\{[A-Za-z_][A-Za-z0-9_]*\}|[0-9]*)"
_REDIR_RE = re.compile(r"^" + _FD_PREFIX + r"(&>>|&>|>>|>\||>&|<&|<>|<|>)")
# OUTPUT redirections only.  Only these can carry a value past a capture --
# `_v=$(printf %s "$PAT" >&2)` is the escape #1012 measured.  An INPUT
# redirection (`<`, `<<`, `<<<`) feeds the command and cannot escape anything,
# so counting it would flag every captured here-string.
#
# A `{name}` prefix is deliberately NOT here.  `{fd}>file` allocates a NEW
# descriptor and binds it to the variable; fd 1 is untouched, so nothing can
# escape a capture through it.  `_REDIR_RE` above still carries the prefix,
# because the WORD is a redirection and has to be stepped over rather than
# read as a command or an operand.
_OUT_REDIR_RE = re.compile(r"^(?:[0-9]*)(&>>|&>|>>|>\||>&|<>|>)")
# STANDARD OUTPUT redirections only, which is a strictly smaller set.  A
# pipeline carries fd 1, so only a redirection that moves fd 1 can send the
# value somewhere the pipe does not reach: `>file`, `1>file`, `>&2`, `&>file`
# all do; `2>/dev/null` and `2>&1` do not, and reading them as an escape would
# flag `printf '%s' "$PAT" 2>/dev/null | grep -q x`, which puts nothing on a
# stream.  Descriptor 0 is STANDARD INPUT and belongs with them: `0>/dev/null`
# moves fd 0, leaves fd 1 on the pipe, and reading it as an escape flagged a
# line that puts nothing on a stream (#1032 F12).  `{fd}>` belongs with them
# and is likewise absent: bash ALLOCATES a new descriptor there and binds it
# to the variable, so fd 1 stays exactly where it was and the value still
# travels down the pipe.  Reading it as an escape was written as a
# fail-closed default while the lexer could not produce the word at all
# (#1032 round 3 M3); now that it can, the fail-closed reading is simply the
# wrong answer -- measured: `printf '%s' "$PAT" {fd}>&2` puts the value on
# STDOUT.
_STDOUT_REDIR_RE = re.compile(r"^(?:1?)(&>>|&>|>>|>\||>&|>)")
_PRAGMA_RE = re.compile(r"(?<![A-Za-z0-9_])" + PRAGMA + r":[ \t]*(\S.*)?$")


_FD_PREFIX_RE = re.compile(r"^(?:\{[A-Za-z_][A-Za-z0-9_]*\}|[0-9]*)$")
# `_FD_PREFIX_RE`'s `{name}` alternative was UNREACHABLE until #1032 round 3:
# the lexer opened a brace group at every word-initial `{`, so `{fd}` was
# split into a group token and the word `fd}` before any redirection operator
# arrived.  The fix is in the lexer, where `{` is now a reserved word only as
# a COMPLETE TOKEN -- see the `c == "{"` branch -- which lets `{fd}` reach
# this test as one word and keeps it glued to the operator.


def _is_fd_prefix(word):
    """May this partial word stay glued to a following redirection operator?

    Only an IO_NUMBER or a `{name}` descriptor variable may -- and the empty
    word, which is the ordinary `cmd >file` spelling.  Everything else is a
    WORD that the operator terminates.
    """
    return bool(_FD_PREFIX_RE.match(word))


def redirects_stdout(seg):
    """Does any word in this segment move fd 1 away from where it would go?"""
    return any(_STDOUT_REDIR_RE.match(w) for w in seg.words)


def _find_substitutions(s, quotes_are_literal=False, include_arithmetic=False):
    """Yield (body, start_offset, end_offset) for every COMMAND SUBSTITUTION.

    Used for the two places the main loop hands over a span of text WHOLE
    rather than lexing it as structure: an array assignment's parenthesised
    list and an interpolating here-doc BODY.  Both are data as far as the
    surrounding line is concerned, and bash still RUNS any `$( )` inside them.

    The two spans do NOT quote alike, which is what `quotes_are_literal` is
    for.  In the array list a `'` opens ordinary single-quoting and suppresses
    expansion.  In an INTERPOLATING here-doc body it does not: quoting is
    performed on the DELIMITER, not inside the body, so a `'` there is a
    literal apostrophe and bash still runs a `$( )` written between two of
    them.  Reading the body under ordinary quoting made

        read x <<EOF
        '$(printf '%s' "$GH_TOKEN" >&2)'
        EOF

    a silent false negative: the substitution was never found, the reference
    was attributed to `read` -- which stores rather than writes -- and bash
    put the value on stderr (#1032 round 3 P1).

    Backslash keeps its two-character skip in both modes.  Inside an
    interpolating body bash honours `\\` before `$`, `` ` ``, `\\` and
    newline and leaves it literal elsewhere, and neither reading changes
    where a `$(` or a backtick begins.

    The heredoc diagnostic caller can opt into arithmetic spans, parameter
    arithmetic operands and conservative tails when the existing exact reader
    cannot prove a command substitution's end. Existing bounded readers supply
    the spans; no arithmetic value or case grammar is evaluated. Default callers
    still inventory command substitutions only.

    Only the outermost span is yielded -- anything nested inside is found
    when that body is lexed on its own.

    Inside double quotes an apostrophe is literal (#1494).  See
    `_ExactReadUnavailable` for how that reading falls back.
    """
    if quotes_are_literal:
        return _find_substitutions_legacy(s, quotes_are_literal, include_arithmetic)
    try:
        return _find_substitutions_exact(s, include_arithmetic)
    except _ExactReadUnavailable:
        return _find_substitutions_legacy(s, quotes_are_literal, include_arithmetic)


def _heredoc_diagnostic_span(text, i):
    """Read a diagnostic candidate with existing bounds, not shell grammar.

    Only the heredoc diagnostic inventory opts in. Legacy `$[ ]` arithmetic
    uses compound bounds, including nested brackets; substring/index operands
    use the existing parameter and brace bounds.
    For a real command-substitution opener whose end the exact reader cannot
    prove, retain the remaining bounded source conservatively. That tail can
    include inert data; it is not a claim that every retained character runs.
    """
    if text[i : i + 2] == "$[":
        close = _find_compound_close(text, i + 1, bracket_span=True)
        end = len(text) if close is None else close + 1
        return text[i + 2 : close if close is not None else end], i, end
    if text[i : i + 2] == "$(" and text[i + 2 : i + 3] != "(":
        try:
            _simple_substitution_end(text, i)
        except _ExactReadUnavailable:
            return text[i + 2 :], i, len(text)
    if text[i : i + 2] != "${":
        return None
    j = i + 2
    prefix = text[j : j + 1]
    if prefix in ("#", "!"):
        j += 1
    positional = re.match(r"(?:[0-9]+|[@*])", text[j:])
    if positional:
        j += positional.end()
    else:
        name, j = ident_at(text, j)
        if name is None:
            return None
    op = text[j : j + 1]
    if op != "[" and not (prefix not in ("#", "!") and op == ":"
                             and text[j + 1 : j + 2] not in ("-", "+", "=", "?")):
        return None
    try:
        end = _simple_parameter_end(text, i)
    except _ExactReadUnavailable:
        close = _find_compound_close(text, i + 1)
        if close is None:
            return text[j + 1 :], i, len(text)
        end = close + 1
    return text[j + 1 : end - 1], i, end


def _find_substitutions_exact(s, include_arithmetic=False):
    out = []
    i = 0
    n = len(s)
    in_single = False
    in_double = False
    while i < n:
        c = s[i]
        if c == "\\" and i + 1 < n:
            i += 2
            continue
        if in_single:
            if c == "'":
                in_single = False
            i += 1
            continue
        if c == '"':
            in_double = not in_double
            i += 1
            continue
        if c == "'" and not in_double:
            in_single = True
            i += 1
            continue
        if include_arithmetic and c == "$":
            span = _heredoc_diagnostic_span(s, i)
            if span is not None:
                out.append(span)
                i = span[2]
                continue
        if in_double and c == "$" and s[i + 1 : i + 2] == "{":
            i = _simple_parameter_end(s, i)
            continue
        if (c == "$" and s[i + 1 : i + 2] == "("
                and (include_arithmetic or s[i + 2 : i + 3] != "(")):
            end = _skip_balanced_parens(s, i + 1)
            out.append((s[i + 2 : end - 1], i, end))
            i = end
            continue
        if c == "`":
            close = (_skip_backtick(s, i) - 1 if include_arithmetic
                     else s.find("`", i + 1))
            if close == -1:
                break
            out.append((s[i + 1 : close], i, close + 1))
            i = close + 1
            continue
        i += 1
    return out


def _find_substitutions_legacy(s, quotes_are_literal=False, include_arithmetic=False):
    out = []
    i = 0
    n = len(s)
    in_single = False
    while i < n:
        c = s[i]
        if c == "\\" and i + 1 < n:
            i += 2
            continue
        if in_single:
            if c == "'":
                in_single = False
            i += 1
            continue
        if c == "'" and not quotes_are_literal:
            in_single = True
            i += 1
            continue
        if include_arithmetic and c == "$":
            span = _heredoc_diagnostic_span(s, i)
            if span is not None:
                out.append(span)
                i = span[2]
                continue
        if (c == "$" and s[i + 1 : i + 2] == "("
                and (include_arithmetic or s[i + 2 : i + 3] != "(")):
            end = _skip_balanced_parens(s, i + 1)
            out.append((s[i + 2 : end - 1], i, end))
            i = end
            continue
        if c == "`":
            close = (_skip_backtick(s, i) - 1 if include_arithmetic
                     else s.find("`", i + 1))
            if close == -1:
                break
            out.append((s[i + 1 : close], i, close + 1))
            i = close + 1
            continue
        i += 1
    return out


class Lexer:
    """Segment-aware shell lexer.  Never executes anything it reads."""

    def __init__(self, text):
        self.text = text
        self.logical = []
        self.heredocs = []
        self.func_defs = []  # (name, body_start_index, body_end_index)
        self.quoted_data_offsets = set()  # Read-only function-header context.
        self.comment_offsets = set()
        self.function_source_children = []  # (original body offset, child Lexer)
        # Set when the text ends while a here-doc body is still open.  The
        # scanner has lost sync with the file at that point, and a silent
        # loss of the remainder is the failure mode this gate exists to stop.
        self.unterminated_heredoc = None
        self._sid = 0
        self._run()

    def _absorb_function_context(self, sub, body_offset):
        """Retain child source context without changing tokens or references."""
        self.quoted_data_offsets.update(
            body_offset + i for i in sub.quoted_data_offsets
        )
        self.comment_offsets.update(body_offset + i for i in sub.comment_offsets)
        self.function_source_children.append((body_offset, sub))

    def _absorb_substitutions(
        self, inner, parent_seg, base_line, cur_ll,
        in_heredoc_body=False, source_offset=0,
    ):
        """Lex the `$( )` bodies inside `inner`; return `inner` with them masked.

        Each substitution is a CAPTURING child of `parent_seg`: its standard
        output becomes the surrounding word, so it reaches a stream only
        through the parent -- or through a redirection that escapes the
        capture, which is the escape `reaches_output` already measures.

        The masked return value is what the caller then scans for ORDINARY
        references, so a name inside a substitution is reported once, by the
        segment that actually runs it.
        """
        # A here-doc body does not quote the way an array list does: a `'`
        # there is a literal apostrophe and suppresses nothing.
        spans = _find_substitutions(inner, quotes_are_literal=in_heredoc_body)
        if not spans:
            return inner
        pieces = []
        cursor = 0
        for body, start, end in spans:
            pieces.append(inner[cursor:start])
            pieces.append(re.sub(r"[^\n]", " ", inner[start:end]))
            cursor = end
            body_line = base_line + inner[:start].count("\n")
            sub = Lexer(body)
            prefix = 2 if inner[start : start + 2] == "$(" else 1
            body_offset = source_offset + start + prefix
            self._absorb_function_context(sub, body_offset)
            for ll in sub.logical:
                for seg in ll.segments:
                    if seg.parent is None:
                        seg.parent = parent_seg
                        seg.parent_is_capture = True
                cur_ll.segments.extend(ll.segments)
                for r in ll.refs:
                    r.line = body_line + (r.line - 1)
                    r.in_heredoc_body = in_heredoc_body
                    cur_ll.refs.append(r)
        pieces.append(inner[cursor:])
        return "".join(pieces)

    def _finish_heredoc(self, hd, cur_ll):
        """Grade a completed here-doc body: substitutions first, then names."""
        if not hd.interpolating or not hd.body_lines:
            return
        start_line = hd.body_lines[0][0]
        body = "\n".join(raw for _lno, raw in hd.body_lines)
        source_offset = sum(
            len(raw) + 1 for raw in self.text.split("\n")[: start_line - 1]
        )
        masked = self._absorb_substitutions(
            body, hd.owner, start_line, cur_ll, in_heredoc_body=True,
            source_offset=source_offset,
        )
        for offset, raw in enumerate(masked.split("\n")):
            for name, in_ew in _iter_refs_ew(raw):
                r = Ref(name, start_line + offset, hd.owner)
                r.heredoc_owner = hd.owner
                r.in_heredoc_body = True
                # An error word is written by BASH, not by the here-doc's
                # owner, so it reaches a stream independently of whether that
                # owner emits.  Without this the reference was attributed to
                # the safe `read` and graded clean (#1032 round 6 P1).
                r.in_error_word = in_ew
                cur_ll.refs.append(r)

    # -- helpers ---------------------------------------------------------
    def _new_segment(self, parent, capture, line):
        self._sid += 1
        seg = Segment(self._sid, parent, capture, line)
        return seg

    def _run(self):
        text = self.text
        n = len(text)
        i = 0
        line = 1

        cur_ll = LogicalLine(1)
        self.logical.append(cur_ll)

        # Level stack.  Each level: dict(seg=..., parent=..., capture=bool,
        # close=str, word=[chars], word_started=bool)
        top = {
            "seg": self._new_segment(None, False, line),
            "capture": False,
            "kind": "top",
            "word": [],
        }
        cur_ll.segments.append(top["seg"])
        levels = [top]

        # Quote stack, innermost last.  Entries: "'", '"', "${", "$((".
        #
        # Quoting is PER LEVEL: inside `$( ... )` bash restarts it, so the
        # inner `"` of `"$(f "${VAR:-}")"` OPENS a string rather than closing
        # the outer one.  One shared stack reads that inner quote as a close,
        # then swallows the `)` that ends the substitution, and everything
        # after it lands in one runaway segment whose command word is
        # unresolvable -- measured as 14 false positives over this tree.
        # The stack is saved on the level being left and restored on return.
        quotes = []

        pending_heredocs = []  # HereDoc objects awaiting a body
        in_heredoc = None

        case_depth = [0]
        # True while the last structural break was a `|` and no word has been
        # read since.  A pipeline whose `|` ends the physical line CONTINUES
        # on the next one -- `printf '%s' "$PAT" |\n  gh auth login
        # --with-token` is one command list, and ending the logical line at
        # the newline would strand the emitter with no consumer.
        pipe_open = [False]

        def cur_level():
            return levels[-1]

        def expanding():
            return "'" not in quotes

        def finish_word():
            lv = cur_level()
            if lv["word"]:
                w = "".join(lv["word"])
                lv["seg"].words.append(w)
                lv["word"] = []
                pipe_open[0] = False
                if w == "case":
                    case_depth[0] += 1
                elif w == "esac" and case_depth[0] > 0:
                    case_depth[0] -= 1

        def in_assign_prefix():
            """True when the reference sits in an env-assignment PREFIX.

            `GH_TOKEN="$OP_PREFLIGHT_REVIEWER_PAT" "$cmd" ...` puts the value
            in the child's ENVIRONMENT, not on a stream, and it is the fleet's
            standard way of handing a credential to a command whose word is
            itself a variable.  The prefix only counts while no command word
            has been seen yet, so `echo x=$GH_TOKEN` is not mistaken for one.
            """
            lv = cur_level()
            for w in lv["seg"].words:
                if w in RESERVED_WORDS:
                    continue  # `if ! GH_TOKEN="$PAT" "$checker" ...`
                if not _ASSIGN_RE.match(w):
                    return False
            return bool(_ASSIGN_RE.match("".join(lv["word"])))

        def start_segment(pipe=False):
            finish_word()
            lv = cur_level()
            prev = lv["seg"]
            seg = self._new_segment(lv["seg"].parent, lv["capture"], line)
            seg.parent = lv["seg"].parent
            # `( echo a; printf '%s' "$PAT" ) >&2` -- every command in the
            # subshell shares the subshell's fate, so the flag travels with
            # the level, not just with its first segment.
            seg.parent_is_subshell = lv.get("subshell", False)
            if pipe:
                prev.pipe_to = seg
            lv["seg"] = seg
            cur_ll.segments.append(seg)
            pipe_open[0] = pipe

        def end_logical_line(next_line):
            nonlocal cur_ll
            finish_word()
            cur_ll = LogicalLine(next_line)
            self.logical.append(cur_ll)
            lv = levels[0]
            seg = self._new_segment(None, False, next_line)
            lv["seg"] = seg
            cur_ll.segments.append(seg)

        while i < n:
            c = text[i]
            if "'" in quotes or '"' in quotes:
                self.quoted_data_offsets.add(i)

            # ---- inside a here-doc body ----
            if in_heredoc is not None:
                eol = text.find("\n", i)
                if eol == -1:
                    eol = n
                raw = text[i:eol]
                probe = raw.lstrip("\t") if in_heredoc.strip_tabs else raw
                if probe == in_heredoc.delim:
                    # Graded WHOLE, at the terminator, rather than line by
                    # line: a `$( )` in the body can span lines, and a
                    # per-line scan can only see names (#1032 F4).
                    self._finish_heredoc(in_heredoc, cur_ll)
                    in_heredoc = None
                else:
                    in_heredoc.body_lines.append((line, raw))
                i = eol + 1
                line += 1
                if in_heredoc is None:
                    if pending_heredocs:
                        in_heredoc = pending_heredocs.pop(0)
                    elif len(levels) > 1:
                        # A here-doc inside `$( ... )`: the substitution is
                        # still open, so this is a segment break, not the end
                        # of the logical line.  Ending the line here would
                        # reset only the OUTER level and strand the open one.
                        start_segment()
                    else:
                        end_logical_line(line)
                continue

            # ---- single quotes ----
            if quotes and quotes[-1] == "'":
                if c == "'":
                    quotes.pop()
                elif c == "\n":
                    line += 1
                cur_level()["word"].append(c)
                i += 1
                continue

            # ---- backslash escape (not inside single quotes) ----
            if c == "\\":
                if i + 1 < n and text[i + 1] == "\n":
                    # Line continuation: the logical line continues.
                    i += 2
                    line += 1
                    continue
                if i + 1 < n:
                    cur_level()["word"].append(c)
                    cur_level()["word"].append(text[i + 1])
                    if text[i + 1] == "\n":
                        line += 1
                    i += 2
                    continue
                cur_level()["word"].append(c)
                i += 1
                continue

            # ---- comment: only at word-initial position, unquoted, depth 0 ----
            if (
                c == "#"
                and not quotes
                and not cur_level()["word"]
                and (i == 0 or text[i - 1] in _WORD_BREAK_BEFORE_COMMENT)
            ):
                eol = text.find("\n", i)
                if eol == -1:
                    eol = n
                comment = text[i:eol]
                self.comment_offsets.update(range(i, eol))
                m = _PRAGMA_RE.search(comment)
                if m:
                    reason = (m.group(1) or "").strip()
                    if reason:
                        cur_ll.pragma_reasons.append(reason)
                    else:
                        cur_ll.pragma_bare = True
                i = eol
                continue

            # ---- expansions and quotes ----
            if c == "$" and i + 1 < n:
                nxt = text[i + 1]
                if nxt == "(" and i + 2 < n and text[i + 2] == "(":
                    quotes.append("$((")
                    cur_level()["word"].append("$((")
                    i += 3
                    continue
                if nxt == "(":
                    # command substitution: a capturing level
                    parent_seg = cur_level()["seg"]
                    seg = self._new_segment(parent_seg, True, line)
                    cur_ll.segments.append(seg)
                    levels.append(
                        {
                            "seg": seg,
                            "capture": True,
                            "kind": "cmdsub",
                            "word": [],
                            "saved_quotes": quotes,
                        }
                    )
                    quotes = []
                    i += 2
                    continue
                if nxt == "{":
                    # `${?` is the SAME brace level as `${`, marked so that a
                    # reference found later inside it knows it is in an error
                    # WORD the expansion itself writes.  It is a distinct
                    # marker rather than a parallel counter because the pop on
                    # `}` has to stay exactly symmetric with the push.
                    quotes.append(
                        "${?" if error_word_expansion_at(text, i) else "${"
                    )
                    cur_level()["word"].append("${")
                    # `${NAME...}`: `braced_ref_at` is the single decider,
                    # shared with the here-doc body scanner.  Anything nested
                    # inside the braces is found by this same loop on its
                    # own `$`, which is what makes `${UNSET:-$GH_TOKEN}` a
                    # reference to GH_TOKEN.
                    if expanding():
                        name = braced_ref_at(text, i)
                        if name:
                            r = Ref(
                                name,
                                line,
                                cur_level()["seg"],
                                in_assign_prefix(),
                            )
                            r.in_error_word = "${?" in quotes[:-1]
                            cur_ll.refs.append(r)
                    i += 2
                    continue
                # a plain variable reference
                if expanding():
                    nm, _end = ident_at(text, i + 1)
                    if nm is not None and nm in TOKEN_NAME_SET:
                        r = Ref(
                            nm,
                            line,
                            cur_level()["seg"],
                            in_assign_prefix(),
                        )
                        r.in_error_word = "${?" in quotes
                        cur_ll.refs.append(r)
                cur_level()["word"].append(c)
                i += 1
                continue

            if c == "}" and quotes and quotes[-1] in ("${", "${?"):
                quotes.pop()
                cur_level()["word"].append(c)
                i += 1
                continue

            if c == ")" and quotes and quotes[-1] == "$((":
                if i + 1 < n and text[i + 1] == ")":
                    quotes.pop()
                    cur_level()["word"].append("))")
                    i += 2
                    continue

            if c == "'" and (not quotes or quotes[-1] in ("${", "${?", "$((")):
                quotes.append("'")
                cur_level()["word"].append(c)
                i += 1
                continue

            if c == '"':
                if quotes and quotes[-1] == '"':
                    quotes.pop()
                else:
                    quotes.append('"')
                cur_level()["word"].append(c)
                i += 1
                continue

            # Inside `${...}` or `$((...))` or `"..."`: track a reference by
            # name but do not treat operators as structure.
            if quotes:
                if c == "\n":
                    line += 1
                cur_level()["word"].append(c)
                i += 1
                continue

            if c == "`":
                # Backticks: treat like a capturing command substitution.
                close = text.find("`", i + 1)
                if close == -1:
                    close = n
                inner = text[i + 1 : close]
                parent_seg = cur_level()["seg"]
                sub = Lexer(inner)
                self._absorb_function_context(sub, i + 1)
                for ll in sub.logical:
                    # Re-parent the segments the sub-lexer left PARENTLESS,
                    # the same rule `_absorb_substitutions` uses.  Re-parenting
                    # the segment each REFERENCE sits in instead cut the link
                    # to whatever ran between it and the substitution: a
                    # `( ... )` writes to its enclosing command, and pointing
                    # the inner command straight at the outer word made
                    # ``v=`( printf '%s' "$PAT" )` `` read as an emission that
                    # nothing captured.
                    for seg2 in ll.segments:
                        if seg2.parent is None:
                            seg2.parent = parent_seg
                            seg2.parent_is_capture = True
                    for r in ll.refs:
                        # Re-line the reference but keep what the sub-lexer
                        # learned about it.  A bare copy dropped
                        # `in_error_word`, so ``v=`: "${U:?$PAT}"` `` -- which
                        # bash writes to stderr past the capture -- read clean
                        # (#1564 review).
                        ref = Ref(r.name, line, r.seg, r.in_assign_prefix)
                        ref.in_error_word = r.in_error_word
                        ref.heredoc_owner = r.heredoc_owner
                        ref.in_heredoc_body = r.in_heredoc_body
                        cur_ll.refs.append(ref)
                    cur_ll.segments.extend(ll.segments)
                line += inner.count("\n")
                cur_level()["word"].append("`sub`")
                i = close + 1
                continue

            # ---- here-doc / here-string openers ----
            if c == "<" and i + 1 < n and text[i + 1] == "<":
                if i + 2 < n and text[i + 2] == "<":
                    # here-string: the following word belongs to this segment
                    cur_level()["seg"].words.append("<<<")
                    i += 3
                    continue
                j = i + 2
                strip_tabs = False
                if j < n and text[j] == "-":
                    strip_tabs = True
                    j += 1
                while j < n and text[j] in " \t":
                    j += 1
                delim_chars = []
                interpolating = True
                while j < n:
                    ch = text[j]
                    # `<<$'EOF'` and `<<$"EOF"`.  Bash strips the `$` AND the
                    # quotes and terminates at the bare word, with expansion
                    # disabled.  Stripping only the quotes recorded the
                    # delimiter as `$EOF`, no body line ever matched it, and
                    # the scanner ran to end of file and reported the file as
                    # carrying an unterminated here-doc -- a FALSE finding on
                    # valid shell that reds the required lint gate (#1032
                    # round 6 P2).
                    if ch == "$" and j + 1 < n and text[j + 1] in "'\"":
                        interpolating = False
                        q = text[j + 1]
                        j += 2
                        while j < n and text[j] != q:
                            delim_chars.append(text[j])
                            j += 1
                        j += 1
                        continue
                    if ch in "'\"":
                        interpolating = False
                        q = ch
                        j += 1
                        while j < n and text[j] != q:
                            delim_chars.append(text[j])
                            j += 1
                        j += 1
                        continue
                    if ch == "\\":
                        interpolating = False
                        j += 1
                        if j < n:
                            delim_chars.append(text[j])
                            j += 1
                        continue
                    # The delimiter is a WORD, and a word ends at a shell
                    # METACHARACTER -- not at "the next character outside an
                    # alphanumeric allow-list".  `read x <<E@F` names the
                    # delimiter `E@F`; stopping at the `@` recorded `E`, no
                    # line ever matched it, and the scanner stayed inside a
                    # here-doc body to end of file, missing every later
                    # emitter (#1032 F3).
                    if ch in " \t\n;&|()<>":
                        break
                    delim_chars.append(ch)
                    j += 1
                    continue
                delim = "".join(delim_chars)
                if delim:
                    hd = HereDoc(delim, interpolating, strip_tabs, cur_level()["seg"])
                    pending_heredocs.append(hd)
                    self.heredocs.append(hd)
                    cur_level()["seg"].words.append("<<")
                i = j
                continue

            # ---- structure ----
            if c == "\n":
                finish_word()
                line += 1
                i += 1
                if pending_heredocs:
                    in_heredoc = pending_heredocs.pop(0)
                    continue
                if pipe_open[0] and not cur_level()["seg"].words:
                    # A trailing `|` continues the command list onto the next
                    # physical line, exactly as a trailing `\` does.  Ending
                    # the logical line here would drop the pipe link and read
                    # the emitter as writing to the terminal.
                    continue
                if len(levels) > 1:
                    # newline inside `$( ... )` is a segment break, not a
                    # logical-line break
                    start_segment()
                    continue
                end_logical_line(line)
                continue

            if c in " \t":
                finish_word()
                i += 1
                continue

            if c == ";":
                start_segment()
                i += 1
                continue

            # ---- redirection operators ----
            # Consumed WHOLESALE, because `>&2` and `&>file` carry a `&` and
            # `>|` a `|`.  Reading either as a list operator splits the logical
            # command in half and the emitter behind it is never seen -- the
            # `>&2 echo "$PAT"` and `$(... >&2)` escapes measured on #1012.
            if c in "<>" and text[i + 1 : i + 2] == "(":
                # process substitution: a NON-capturing level, so the emitter
                # inside is judged on its own merits
                parent_seg = cur_level()["seg"]
                seg = self._new_segment(parent_seg, False, line)
                cur_ll.segments.append(seg)
                levels.append(
                    {
                        "seg": seg,
                        "capture": False,
                        "kind": "procsub",
                        "word": [],
                        "saved_quotes": quotes,
                    }
                )
                quotes = []
                i += 2
                continue

            if c in "<>":
                # A redirection operator is a metacharacter: it ENDS the word
                # in front of it unless that word is a bare IO_NUMBER (`2>&1`)
                # or a `{name}` descriptor variable.  `printf>&2 '%s' "$PAT"`
                # is the word `printf` followed by `>&2`, and gluing the two
                # into one token hid the emitter behind a redirection-only
                # word (#1032 F1).
                if not _is_fd_prefix("".join(cur_level()["word"])):
                    finish_word()
                j = i + 1
                if c == ">" and text[j : j + 1] in (">", "|"):
                    j += 1
                elif text[j : j + 1] == "&":
                    j += 1
                    while j < n and text[j].isdigit():
                        j += 1
                    if text[j : j + 1] == "-":
                        j += 1
                elif c == "<" and text[j : j + 1] == ">":
                    j += 1
                cur_level()["word"].append(text[i:j])
                i = j
                continue

            if c == "&":
                if text[i + 1 : i + 2] == "&":
                    start_segment()
                    i += 2
                    continue
                if text[i + 1 : i + 2] == ">":
                    # `&>` takes no descriptor prefix at all, and bash still
                    # reads it as a redirection when it abuts a word:
                    # `printf&>f '%s' "$PAT"` writes the value to `f`.
                    finish_word()
                    j = i + 2
                    if text[j : j + 1] == ">":
                        j += 1
                    cur_level()["word"].append(text[i:j])
                    i = j
                    continue
                start_segment()
                i += 1
                continue

            if c == "|":
                if i + 1 < n and text[i + 1] == "|":
                    start_segment()
                    i += 2
                    continue
                # `|&` is `2>&1 |`.  Its consumer is a real command, but the
                # `&` is consumed by the `&` branch below as its own break, so
                # the recorded consumer is an EMPTY segment -- which the
                # unresolved-consumer branch of `reaches_output` fails closed
                # on.  That is the conservative direction and it is declared.
                start_segment(pipe=True)
                i += 1
                continue

            if c == "(":
                word_so_far = "".join(cur_level()["word"])
                if word_so_far.endswith("="):
                    # An ARRAY ASSIGNMENT.  `args=(echo "$PAT")` stores two
                    # strings and writes nothing; reading the `(` as a command
                    # position is how #1012 round 4 flagged it.  The whole
                    # parenthesised list belongs to the assignment word.
                    #
                    # The ELEMENTS are data, but bash still RUNS a `$( )`
                    # among them, and skipping the span without lexing meant
                    # `args=($(printf '%s' "$PAT" >&2))` was never looked at
                    # (#1032 F2).  Each substitution is absorbed as a capture
                    # under this assignment, so the value it prints lands in
                    # the array -- and a redirection that escapes the capture
                    # is flagged exactly as it is anywhere else.
                    j = _skip_balanced_parens(text, i)
                    inner = text[i:j]
                    self._absorb_substitutions(
                        inner, cur_level()["seg"], line, cur_ll, source_offset=i
                    )
                    cur_level()["word"].append(inner.replace("\n", " "))
                    line += inner.count("\n")
                    i = j
                    continue
                # Record declarations only for builtin provenance; body-span
                # discovery remains the independent #1647 seam.
                if re.match(r"\((?:[ \t]|\\\n)*\)", text[i:]):
                    seg = cur_level()["seg"]
                    if word_so_far:
                        seg._function_binding = (len(seg.words), word_so_far)
                    elif seg.words:
                        seg._function_binding = (len(seg.words) - 1, seg.words[-1])
                if not word_so_far:
                    # subshell / case-pattern parens.  A subshell does not
                    # capture anything ITSELF, so `( echo "$PAT" )` at the top
                    # level reaches the terminal -- but its standard output is
                    # wherever the ENCLOSING command's output goes, so a
                    # subshell written inside `$( )` is captured exactly as a
                    # bare command there is.  Hard-coding a False parent
                    # dropped that shield and made `v=$( ( printf '%s' "$PAT"
                    # ) )` a false positive on a required check (#1032 F10).
                    #
                    # The link recorded is STRUCTURAL -- "these commands are
                    # inside a subshell written in THAT segment" -- rather
                    # than a copy of the enclosing level's capture flag.
                    # Copying the flag answered "captured?" correctly only
                    # where the enclosing level knew, and it lost the two
                    # things the wrapper segment holds: the redirection
                    # written after the `)` (missed) and the re-parenting
                    # `_absorb_substitutions` performs on an array
                    # assignment's `$( )` (missed the other way, so the
                    # same subshell read clean in one context and leaked
                    # in the other) -- #1032 round 2, F10 and F2 x F10.
                    parent_seg = cur_level()["seg"]
                    seg = self._new_segment(parent_seg, False, line)
                    seg.parent_is_subshell = True
                    cur_ll.segments.append(seg)
                    levels.append(
                        {
                            "seg": seg,
                            "capture": False,
                            "subshell": True,
                            "kind": "subshell",
                            "word": [],
                            "saved_quotes": quotes,
                        }
                    )
                    quotes = []
                    i += 1
                    continue
                cur_level()["word"].append(c)
                i += 1
                continue

            if c == ")":
                if len(levels) > 1:
                    finish_word()
                    kind = levels[-1]["kind"]
                    quotes = levels[-1]["saved_quotes"]
                    levels.pop()
                    if kind == "cmdsub":
                        cur_level()["word"].append("$()")
                    elif case_depth[0] > 0:
                        # `case x in (pat) cmd ;;` -- the pattern's `)` ends
                        # the pattern, and the command after it is its own
                        # segment.
                        start_segment()
                    i += 1
                    continue
                if case_depth[0] > 0:
                    # `case x in pat) cmd ;;` -- an unmatched `)` inside a
                    # case body is a pattern terminator, never part of the
                    # command, so the emitter after it heads its own segment.
                    start_segment()
                    i += 1
                    continue
                cur_level()["word"].append(c)
                i += 1
                continue

            if c == "{" and not cur_level()["word"]:
                # `{` is a RESERVED WORD, and a reserved word is only that
                # when it is a COMPLETE TOKEN -- bash needs a blank or a
                # metacharacter after it.  `{x,y}` and `{fd}>&2` are ordinary
                # WORDS, and opening a group at either one split the segment
                # and left the real command word behind it: `echo {x,y}
                # "$PAT"` resolved its command to `x,y}` and read CLEAN while
                # bash printed the value, and `{fd}>&2 printf '%s' "$PAT"`
                # resolved to `fd}` the same way (#1032 round 3 M3).  Falling
                # through to the ordinary word path lets `{fd}` accumulate as
                # a word, which `_is_fd_prefix` then keeps glued to the
                # redirection operator -- one rule for both.
                nxt = text[i + 1 : i + 2]
                if nxt == "" or nxt.isspace() or nxt in ";&|()<>":
                    cur_level()["seg"].words.append("{")
                    start_segment()
                    i += 1
                    continue
                cur_level()["word"].append(c)
                i += 1
                continue

            if c == "}" and not cur_level()["word"]:
                start_segment()
                i += 1
                continue

            cur_level()["word"].append(c)
            i += 1

        if in_heredoc is not None:
            # End of file with a here-doc still open.  Bash warns and treats
            # the remainder as the body; the scanner records the delimiter it
            # never found so `scan_text` can report the loss of sync rather
            # than let it shrink the scan silently.
            self._finish_heredoc(in_heredoc, cur_ll)
            self.unterminated_heredoc = (in_heredoc.delim, in_heredoc.owner.line)

        finish_word()


def _skip_backtick(text, i):
    """Return the index just past the backtick closing the one at `i`.

    A backslash escapes the next character, so `\\`` inside the body is data
    and does not close it.  Returns len(text) when the body never closes.
    """
    j = i + 1
    n = len(text)
    while j < n:
        if text[j] == "\\":
            j += 2
            continue
        if text[j] == "`":
            return j + 1
        j += 1
    return n


class _ExactReadUnavailable(Exception):
    """Raised when a double-quoted span holds a construct read only by parsing.

    An apostrophe inside double quotes is literal in bash, but the structural
    walkers below read it as opening a single-quoted span, lose the real
    close, and scan a leaking file clean (#1494).  Reading it as literal is
    only safe where the walker can also find where every construct inside the
    string ENDS.  For a `$( )` that means parsing its body as command grammar
    -- case patterns, `#` comments, nested parentheses, here-docs -- and every
    structural attempt at that reopened verdicts the walkers already got right
    (#1498).

    So each walker has two readings.  The exact one accepts only text it can
    read exactly: literal characters, backticks (bash ends one at the first
    unescaped backtick), and `$( )`, `$(( ))` and `${ }` spans simple enough
    that their end is unambiguous.  On anything else it raises this, and the
    caller re-reads the WHOLE input with the walker's pre-#1494 `_legacy`
    body, unchanged.  A file therefore gets either the exact reading or
    exactly the reading it had before, never a mixture of the two.
    """


_CASE_WORD_RE = re.compile(r"(?:case|esac)(?![A-Za-z0-9_])")


def _simple_substitution_end(text, i):
    """End of the `$( )` at `i`, or raise when its body needs a parser.

    Simple means the first unquoted `)` closes it: no unquoted `(`, `{`, `#`
    or backtick, no `case`/`esac`, no here-doc, and no `$` expansion inside a
    double-quoted word of the body.  Quoting inside the body is the inner
    command's own.
    """
    j = i + 2
    n = len(text)
    quote = None
    while j < n:
        c = text[j]
        if quote == "'":
            if c == "'":
                quote = None
            j += 1
            continue
        if c == "\\":
            j += 2
            continue
        if quote == '"':
            if c == '"':
                quote = None
            elif c == "`" or (c == "$" and text[j + 1 : j + 2] in ("(", "{")):
                raise _ExactReadUnavailable()
            j += 1
            continue
        if c in "'\"":
            quote = c
            j += 1
            continue
        if c in "({#`" or text.startswith("<<", j):
            raise _ExactReadUnavailable()
        if c == ")":
            return j + 1
        if (j == 0 or not (text[j - 1].isalnum() or text[j - 1] == "_")) \
                and _CASE_WORD_RE.match(text, j):
            raise _ExactReadUnavailable()
        j += 1
    raise _ExactReadUnavailable()


def _simple_arithmetic_end(text, i):
    """End of the `$(( ))` at `i`, or raise when it holds quotes or expansions."""
    depth = 0
    j = i + 1
    n = len(text)
    while j < n:
        c = text[j]
        if c in "'\"`\\{":
            raise _ExactReadUnavailable()
        if c == "(":
            depth += 1
        elif c == ")":
            depth -= 1
            if depth == 0:
                return j + 1
        j += 1
    raise _ExactReadUnavailable()


def _simple_parameter_end(text, i):
    """End of the `${ }` at `i`, or raise when its word holds quotes or expansions."""
    j = i + 2
    n = len(text)
    while j < n:
        c = text[j]
        if c == "}":
            return j + 1
        if c in "'\"`\\${":
            raise _ExactReadUnavailable()
        j += 1
    raise _ExactReadUnavailable()


def _double_quoted_construct_end(text, i):
    """Exact end of an expansion starting at `i` inside double quotes, or None."""
    if text[i] == "`":
        return _skip_backtick(text, i)
    if text[i] != "$":
        return None
    nxt = text[i + 1 : i + 2]
    if nxt == "(":
        if text[i + 2 : i + 3] == "(":
            return _simple_arithmetic_end(text, i)
        return _simple_substitution_end(text, i)
    if nxt == "{":
        return _simple_parameter_end(text, i)
    return None


def _skip_balanced_parens(text, start):
    """Return the index just past the `)` matching the `(` at `start`."""
    try:
        return _skip_balanced_parens_exact(text, start)
    except _ExactReadUnavailable:
        return _skip_balanced_parens_legacy(text, start)


def _skip_balanced_parens_exact(text, start):
    depth = 0
    i = start
    n = len(text)
    quotes = []
    while i < n:
        c = text[i]
        if quotes and quotes[-1] == "'":
            if c == "'":
                quotes.pop()
            i += 1
            continue
        if c == "\\":
            i += 2
            continue
        if c == "'" and not quotes:
            quotes.append("'")
            i += 1
            continue
        if c == '"':
            if quotes:
                quotes.pop()
            else:
                quotes.append('"')
            i += 1
            continue
        if quotes:
            end = _double_quoted_construct_end(text, i)
            i = i + 1 if end is None else end
            continue
        if c == "(":
            depth += 1
        elif c == ")":
            depth -= 1
            if depth == 0:
                return i + 1
        i += 1
    return n


def _skip_balanced_parens_legacy(text, start):
    depth = 0
    i = start
    n = len(text)
    quotes = []
    while i < n:
        c = text[i]
        if quotes and quotes[-1] == "'":
            if c == "'":
                quotes.pop()
            i += 1
            continue
        if c == "\\":
            i += 2
            continue
        if c == "'":
            quotes.append("'")
            i += 1
            continue
        if c == '"':
            if quotes and quotes[-1] == '"':
                quotes.pop()
            else:
                quotes.append('"')
            i += 1
            continue
        if quotes:
            i += 1
            continue
        if c == "(":
            depth += 1
        elif c == ")":
            depth -= 1
            if depth == 0:
                return i + 1
        i += 1
    return n


def ident_at(text, pos):
    """Match a shell identifier at `pos`, transparently across `\\<newline>`.

    Bash removes a LINE CONTINUATION before it parses the expansion, so
    `$GH_\\<newline>TOKEN` names `GH_TOKEN` and prints its value.  Matching
    `_IDENT_RE` against the raw text stopped at the backslash, saw the unknown
    prefix `GH_`, and reported nothing -- a bypass in the same family as the
    forgeable pragma #1012 shipped, since it hides a credential NAME from the
    only test that looks for one (#1032 round 6 P1).

    Returns (name, end_index), or (None, pos) when no identifier is there.
    A continuation immediately AFTER the name is consumed too, because bash
    removes that one as well and the caller reads the expansion OPERATOR from
    `end_index`.
    """
    out = []
    i = pos
    n = len(text)
    while i < n:
        if text[i] == "\\" and i + 1 < n and text[i + 1] == "\n":
            i += 2
            continue
        c = text[i]
        # ASCII, not `str.isalpha()`/`str.isalnum()`.  Python accepts Unicode
        # letters and digits; bash's parameter-name grammar is exactly
        # `[A-Za-z_][A-Za-z0-9_]*`, so a non-ASCII character ENDS the name in
        # bash while Python swallowed it into one longer unknown name.
        # `echo "$GH_TOKEN\u00e9"` expands GH_TOKEN and prints the whole value
        # followed by the stray character, under both LC_ALL=C and
        # LC_ALL=C.UTF-8, while the scanner read `GH_TOKEN\u00e9` and reported
        # clean (#1032 round 6 P1).  Widening a name can only ever HIDE a
        # credential, so this is a fail-open the grammar itself closes.
        ok = _ASCII_NAME_START(c) if not out else _ASCII_NAME_CONT(c)
        if not ok:
            break
        out.append(c)
        i += 1
    if not out:
        return None, pos
    return "".join(out), i


def _ASCII_NAME_START(c):
    return ("A" <= c <= "Z") or ("a" <= c <= "z") or c == "_"


def _ASCII_NAME_CONT(c):
    return _ASCII_NAME_START(c) or ("0" <= c <= "9")


def _error_word_parameter_end(text, brace_open, allow_positionals=False):
    """Guard endpoint; only HD callers opt into positional/indirect guards."""
    j = brace_open + 2
    if text[j : j + 1] == "#":
        return None
    if text[j : j + 1] == "!":
        if not allow_positionals:
            return None
        j += 1
    name, end = ident_at(text, j)
    if name is not None:
        return end
    if allow_positionals:
        m = re.match(r"(?:[0-9]+|[@*])", text[j:])
        if m is not None:
            return j + m.end()
    return None


def error_word_expansion_at(text, brace_open, allow_positionals=False):
    """Is the `${...}` at `brace_open` the ERROR-WORD form, `:?` or `?`?

    `${VAR:?word}` and `${VAR?word}` make BASH ITSELF write `word` to stderr
    when VAR is unset (or unset/empty), before the enclosing command runs.
    So a credential in that word reaches a stream no matter what the command
    is -- `: "${UNSET:?$PAT}"` and `x=${UNSET:?$PAT}` both print it.

    The operator is matched immediately after the NAME, so the `?` of a
    pattern operator (`${VAR%?}`, `${VAR/?/x}`) is not this.  The name is a
    plain identifier and NOT required to be a credential name: the credential
    is in the WORD, and the variable being tested is usually something else.
    """
    end = _error_word_parameter_end(text, brace_open, allow_positionals)
    if end is None:
        return False
    rest = text[end:]
    return rest.startswith(":?") or rest.startswith("?")




def braced_ref_at(text, brace_open):
    """Decide a `${...}` expansion at `brace_open` (the index of the `$`).

    Returns the credential NAME when the expansion yields that variable's
    VALUE, and None otherwise:

        ${#NAME}      a length            -> None
        ${!NAME}      an indirection      -> None
        ${NAME:+WORD} constant alternate  -> None
        ${NAME+WORD}  constant alternate  -> None
        ${NAME}, ${NAME:-}, ${NAME#p}, ${NAME:0:8}, ...  -> NAME

    A nested expansion inside the braces is never this function's business;
    the caller finds it on its own `$`, which is what makes
    `${UNSET:-$GH_TOKEN}` a reference to GH_TOKEN.

    THE SINGLE DECIDER, called from both the lexer and the here-doc body
    scanner.  #1012's two independent walks over the same line disagreed and
    the divergence became a pragma bypass; there is one of these on purpose.
    """
    j = brace_open + 2
    if j < len(text) and text[j] in "#!":
        return None
    name, end = ident_at(text, j)
    if name is None or name not in TOKEN_NAME_SET:
        return None
    op = text[end : end + 2]
    if op[:2] == ":+" or op[:1] == "+":
        return None
    # `${VAR@a}` expands to the variable's ATTRIBUTES (`x` for an exported
    # one), never to its value, so it is redacted in the same way `${#VAR}`
    # and `${VAR:+set}` are.  The other `@` transforms -- `@A`, `@Q`, `@P`,
    # `@U`, `@u`, `@L`, `@K`, `@k` -- all carry the VALUE through, so only
    # this one operator is excluded (#1032 round 8 P2).
    if op == "@a":
        return None
    return name


def _error_word_spans(s, in_heredoc=False):
    """[start, end) index spans of every `${VAR:?WORD}` / `${VAR?WORD}` WORD.

    BASH ITSELF writes that word to stderr when VAR is unset, before the
    enclosing command runs -- so a credential there reaches a stream no matter
    what the command is. The HD-only opt-in uses existing exact/compound
    parameter bounds, preserving quoted braces and nested expansions; default
    ordinary callers retain their existing reading. The ordinary-line path knows this; the
    here-doc body path reduced its body to bare NAMES and lost it, so
    `read x <<EOF` / `${UNSET:?$PAT}` / `EOF` attributed the reference to the
    safe `read` owner and reported clean (#1032 round 6 P1).
    """
    spans = []
    i = 0
    n = len(s)
    while i + 1 < n:
        if in_heredoc and s[i] == "\\":
            i += 2
            continue
        if s[i] == "$" and s[i + 1] == "{" and error_word_expansion_at(s, i, allow_positionals=in_heredoc):
            end = _error_word_parameter_end(s, i, allow_positionals=in_heredoc)
            rest = s[end:]
            start = end + (2 if rest.startswith(":?") else 1)
            if in_heredoc:
                try:
                    close = _simple_parameter_end(s, i) - 1
                except _ExactReadUnavailable:
                    close = _find_compound_close(s, i + 1)
                spans.append((start, len(s) if close is None else close))
                i = start
                continue
            depth = 1
            k = start
            while k < n:
                if s[k] == "\\":
                    k += 2
                    continue
                if s[k] == "{":
                    depth += 1
                elif s[k] == "}":
                    depth -= 1
                    if depth == 0:
                        break
                k += 1
            spans.append((start, k))
            i = start
            continue
        i += 1
    return spans


def _iter_refs_ew(s):
    """`_iter_refs`, but each name paired with whether it sits in an error word."""
    spans = _error_word_spans(s)

    def in_ew(pos):
        return any(a <= pos < b for a, b in spans)

    return [(nm, in_ew(pos)) for nm, pos in _iter_refs_at(s)]


def _iter_refs(s):
    """Credential names referenced for their VALUE in a raw string.

    Used for interpolating here-doc BODIES, which the lexer hands over
    whole.  Expansion decisions go through `braced_ref_at`, the same
    function the lexer uses.
    """
    return [nm for nm, _pos in _iter_refs_at(s)]


def _iter_refs_at(s):
    """`_iter_refs`, but each name paired with the index it was found at."""
    out = []
    i = 0
    n = len(s)
    while i < n:
        ch = s[i]
        if ch == "\\" and i + 1 < n:
            i += 2
            continue
        if ch == "$":
            if i + 1 < n and s[i + 1] == "{":
                name = braced_ref_at(s, i)
                if name:
                    out.append((name, i))
                i += 2
                continue
            nm, end = ident_at(s, i + 1)
            if nm is not None and nm in TOKEN_NAME_SET:
                out.append((nm, i))
                i = end
                continue
        i += 1
    return out


# ==========================================================================
# Command-word resolution
# ==========================================================================

UNRESOLVED = "<unresolved>"


def _command_word_expands(w):
    """Does this command word carry an UNQUOTED expansion the shell performs?

    `_unquote_command_word` reduces a word to its literal text, which is the
    right answer for `"echo"` and `\\echo` -- quoting suppresses expansion, so
    the literal IS the command.  It is the WRONG answer for `ec{h,}o` and
    `/bin/e[c]ho`: bash brace-expands the first into `echo` and pathname-
    expands the second onto `/bin/echo`, and both printed the credential while
    the literal (`ec{h,}o`, `/bin/e[c]ho`) matched no known emitter and
    defaulted to safe, so `--scan` reported PASS (#1032 round 4 P1).

    Returning True routes the word to UNRESOLVED, which classifies OPAQUE --
    the fail-CLOSED answer, and the same one an unresolvable command word has
    always taken.  Resolving the expansion is not on the table: it depends on
    the files present at run time, which a source-text scanner cannot know.

    The test is deliberately narrow, so it fires on words the shell really
    does rewrite and not on ordinary punctuation:

      * an unquoted `*` or `?` -- always a pathname pattern;
      * an unquoted `[` with a later unquoted `]` -- a bracket pattern.  `[`
        and `[[` as command words carry no closing bracket IN THE SAME WORD
        and so are unaffected, which is what keeps `[ -n "$GH_TOKEN" ]`
        clean;
      * an unquoted `{` with a later unquoted `}` and a `,` or `..` between
        them -- brace expansion needs one of those to expand at all, so
        `a{b}c` stays the literal command word bash runs.

    A word carrying `$` or a backquote never reaches here: it is UNRESOLVED
    already.
    """
    meta = []  # (char, index) for unquoted metacharacters only
    i = 0
    n = len(w)
    while i < n:
        c = w[i]
        if c == "\\":
            i += 2
            continue
        if c == "'":
            j = w.find("'", i + 1)
            if j == -1:
                return False
            i = j + 1
            continue
        if c == '"':
            j = i + 1
            while j < n and w[j] != '"':
                j += 2 if w[j] == "\\" else 1
            i = j + 1
            continue
        if c in "*?[]{}":
            meta.append((c, i))
        i += 1
    kinds = [c for c, _ in meta]
    if "*" in kinds or "?" in kinds:
        return True
    opens = [i for c, i in meta if c == "["]
    closes = [i for c, i in meta if c == "]"]
    if opens and closes and max(closes) > min(opens):
        return True
    braces_open = [i for c, i in meta if c == "{"]
    braces_close = [i for c, i in meta if c == "}"]
    if braces_open and braces_close and max(braces_close) > min(braces_open):
        inner = w[min(braces_open) + 1 : max(braces_close)]
        if "," in inner or ".." in inner:
            return True
    return False


# The ANSI-C escapes bash expands inside `$'...'`.  Anything else after the
# backslash is the character itself, which is bash's own rule.
_ANSI_C_ESCAPES = {
    "n": "\n", "t": "\t", "r": "\r", "a": "\a", "b": "\b",
    "f": "\f", "v": "\v", "e": "\x1b", "E": "\x1b",
    "\\": "\\", "'": "'", '"': '"', "?": "?", "0": "\0",
}


def _unquote_command_word(w):
    """Reduce a command word to a literal, or return None if it is not one."""
    out = []
    i = 0
    n = len(w)
    while i < n:
        c = w[i]
        if c == "\\" and i + 1 < n:
            out.append(w[i + 1])
            i += 2
            continue
        if c == "'":
            j = w.find("'", i + 1)
            if j == -1:
                return None
            out.append(w[i + 1 : j])
            i = j + 1
            continue
        if c == '"':
            j = i + 1
            buf = []
            while j < n and w[j] != '"':
                if w[j] == "\\" and j + 1 < n:
                    buf.append(w[j + 1])
                    j += 2
                    continue
                if w[j] in "$`":
                    return None
                buf.append(w[j])
                j += 1
            if j >= n:
                return None
            out.append("".join(buf))
            i = j + 1
            continue
        # `$'...'` is ANSI-C quoting: bash reduces it to a LITERAL, so it is
        # a literal here too.  Rejecting it with the rest of `$` meant
        # `eval $'echo "$GH_TOKEN"'` handed `_deferred_shell_operands` nothing
        # to recurse into and the deferred text was never scanned -- PASS on a
        # live leak (#1032 round 7 P1).  Only `$'` is decoded; every other `$`
        # is still an expansion and still refuses.
        if c == "$" and i + 1 < n and w[i + 1] == "'":
            j = i + 2
            buf = []
            while j < n and w[j] != "'":
                if w[j] == "\\" and j + 1 < n:
                    buf.append(_ANSI_C_ESCAPES.get(w[j + 1], w[j + 1]))
                    j += 2
                    continue
                buf.append(w[j])
                j += 1
            if j >= n:
                return None
            out.append("".join(buf))
            i = j + 1
            continue
        if c in "$`":
            return None
        out.append(c)
        i += 1
    lit = "".join(out)
    if not lit:
        return None
    return lit


def _basename(lit):
    if "/" in lit:
        lit = lit.rsplit("/", 1)[-1]
    return lit


def resolve_command(seg):
    """Return (command-word-literal | None | UNRESOLVED, has_redirection)."""
    if seg._resolved:
        return seg._cmd
    seg._resolved = True
    words = list(seg.words)
    # Output redirections are collected over the WHOLE segment, not just the
    # words ahead of the command.  `_v=$(printf '%s' "$PAT" >&2)` puts the
    # redirection AFTER the command word, and stopping at the command word is
    # how #1012 let that one escape the capture.
    has_redir = any(_OUT_REDIR_RE.match(w) for w in words)
    idx = 0
    passthru_budget = 6
    while idx < len(words):
        w = words[idx]
        if w in ("{", "}"):
            idx += 1
            continue
        if w == "<<" or w == "<<<":
            idx += 1
            continue
        if _ASSIGN_RE.match(w):
            idx += 1
            continue
        m = _REDIR_RE.match(w)
        if m:
            if m.end() == len(w):
                idx += 2  # operator and its target word
            else:
                idx += 1
            continue
        lit = _unquote_command_word(w)
        if lit is None:
            seg._cmd = (UNRESOLVED, has_redir)
            return seg._cmd
        if lit in RESERVED_WORDS:
            idx += 1
            continue
        base = _basename(lit)
        if base in PASSTHRU and passthru_budget > 0:
            passthru_budget -= 1
            idx += 1
            # step over the wrapper's own options / assignments
            while idx < len(words):
                nw = words[idx]
                nlit = _unquote_command_word(nw)
                if nlit is None:
                    seg._cmd = (UNRESOLVED, has_redir)
                    return seg._cmd
                if nlit == "--":
                    idx += 1
                    break
                if _ASSIGN_RE.match(nw):
                    idx += 1
                    continue
                if nlit.startswith("-"):
                    # env -u NAME / -C DIR / timeout -s SIG take an argument
                    if base == "env" and nlit in ("-u", "-C", "--unset", "--chdir"):
                        idx += 2
                        continue
                    if base == "timeout" and nlit in ("-s", "--signal", "-k"):
                        idx += 2
                        continue
                    if base == "stdbuf" and nlit in ("-i", "-o", "-e"):
                        idx += 2
                        continue
                    idx += 1
                    continue
                break
            if idx >= len(words):
                # a bare wrapper with no command: `env` alone dumps the
                # environment it was handed.
                seg._cmd = (base, has_redir)
                return seg._cmd
            continue
        if _command_word_expands(w):
            # The shell rewrites this word before it names a command, so the
            # literal is not the command.  Fail closed.
            seg._cmd = (UNRESOLVED, has_redir)
            return seg._cmd
        seg._cmd_index = idx
        seg._cmd_literal = lit
        seg._cmd = (base, has_redir)
        return seg._cmd
    seg._cmd = (None, has_redir)
    return seg._cmd


EMIT = "emit"
SAFE = "safe"
ASSIGN = "assign"
OPAQUE = "opaque"


# Operands that provably reach nothing.  `tee /dev/null` is the corpus's own
# spelling of "a tee with no side effect", and a write to the null device is
# the one file operand a source-text scanner can settle without guessing.
_NULL_SINKS = frozenset({"/dev/null", "/dev/zero"})


def tee_file_operands(seg):
    """LITERAL file operands a `tee` in this segment writes.

    `tee FILE` writes FILE **and** stdout, so a `tee` in the middle of a
    pipeline is not a transparent hop: the value lands in a file even though
    the pipeline carries it onward.  That is the same act as
    `printf '%s' "$PAT" > log`, which this gate flags on purpose as the first
    hop of the #993 leak -- and it was invisible while the walk only followed
    the pipe (#1032 F7).

    Only LITERAL operands count.  `tee "$LOG"` names a path the source text
    does not fix, and flagging it would red `lint` fleet-wide on the ordinary
    logging idiom; that residue is declared rather than guessed at.
    """
    cmd, _redir = resolve_command(seg)
    if cmd != "tee":
        return []
    words = list(seg.words)
    # Step to the command word itself, then read what follows it.
    idx = 0
    while idx < len(words):
        w = words[idx]
        lit = _unquote_command_word(w)
        if lit is not None and _basename(lit) == "tee":
            break
        idx += 1
    else:
        return []
    files = []
    end_of_options = False
    skip_next = False
    for w in words[idx + 1 :]:
        if skip_next:
            skip_next = False
            continue
        if w in ("{", "}", "<<"):
            continue
        if w == "<<<":
            skip_next = True  # the here-string word, not a file operand
            continue
        m = _REDIR_RE.match(w)
        if m:
            if m.end() == len(w):
                skip_next = True  # the redirection's target word
            continue
        lit = _unquote_command_word(w)
        if lit is None:
            continue  # a variable operand -- declared residue, not a guess
        if not end_of_options and lit == "--":
            end_of_options = True
            continue
        if not end_of_options and lit.startswith("-") and lit != "-":
            continue
        if lit in _NULL_SINKS:
            continue
        files.append(lit)
    return files


def _printf_literal(raw, literal):
    """Only already literal, non-expanding shell words enter the allowlist."""
    if (literal is None or "$'" in raw
            or raw.replace("\\\n", "").startswith("~")
            or _command_word_expands(raw)):
        return False
    try:
        return shlex.split(raw) == [literal]
    except ValueError:
        return False  # Unproven quoting/escaping never authorizes admission.


def _printf_text_target(raw, target):
    """Owner-ratified lower-case scalar target grammar, not a managed denylist."""
    return (_printf_literal(raw, _unquote_command_word(raw))
            and re.fullmatch(r"[a-z_][a-z0-9_]*", target) is not None
            and target not in {"_", "auto_resume", "histchars"})


def _printf_nondiagnostic_format(raw, literal):
    """The only conversion exempted by Option A is an unmodified %s."""
    return (_printf_literal(raw, literal)
            and "%" not in literal.replace("%s", ""))


def _printf_value_allowed(raw, literal):
    """Literal data or one double-quoted, unmodified ordinary-name expansion."""
    if _printf_literal(raw, literal):
        return True
    return re.fullmatch(r'"\$(?:[A-Za-z_][A-Za-z0-9_]*|\{[A-Za-z_][A-Za-z0-9_]*\})"', raw) is not None


def _printf_assignment_options(seg):
    """Only options before the format/delimiter can select assignment."""
    resolve_command(seg)
    idx = seg._cmd_index
    args = list(_command_arguments(seg.words, idx + 1)) if idx is not None else []
    option_index = 0
    assigned = separate = False
    allowed_targets = True
    while option_index < len(args):
        raw, option = args[option_index]
        if option == "--":
            option_index += 1
            break
        if option == "-v" and option_index + 1 < len(args):
            assigned = separate = True
            option_index += 2
        elif option is not None and option.startswith("-v") and len(option) > 2:
            assigned = True
            allowed_targets = allowed_targets and _printf_text_target(raw, option[2:])
            option_index += 1
        else:
            break
    return args, option_index, assigned, separate, allowed_targets


def _printf_attached_allowed(seg, helpers, args, option_index, allowed_targets):
    # A wrapper, assignment prefix or redirection is outside Option A, even
    # when a particular spelling happens to emit nothing in the oracle.
    return (allowed_targets and seg._cmd_index == 0
            and seg._cmd_literal == "printf" and _printf_literal(seg.words[0], "printf")
            and "printf" not in helpers and not resolve_command(seg)[1]
            and not any(_REDIR_RE.match(word) or word.startswith("<<") for word in seg.words)
            and option_index < len(args)
            and _printf_nondiagnostic_format(*args[option_index])
            and all(_printf_value_allowed(*arg) for arg in args[option_index + 1:]))


def classify(seg, emitter_helpers):
    cmd, _redir = resolve_command(seg)
    if cmd is None:
        return ASSIGN
    if cmd is UNRESOLVED:
        return OPAQUE
    if cmd in OPAQUE_COMMANDS:
        return OPAQUE
    if cmd == "printf":
        # Only option position before the format can assign. Reuse the
        # command/argument boundaries so prefixes and redirections are not
        # printf operands; "--" and a format operand end option parsing.
        idx = seg._cmd_index
        if idx is not None:
            args, option_index, assigned, separate, simple_targets = _printf_assignment_options(seg)
            # Preserve the separate form's existing #1461 verdict.
            if separate:
                return ASSIGN
            # No per-case target/value exclusions: only the ratified grammar
            # can authorize the new attached-assignment exemption.
            if assigned and _printf_attached_allowed(seg, emitter_helpers, args, option_index, simple_targets):
                return ASSIGN
        return EMIT
    if cmd in EMITTERS:
        return EMIT
    if cmd in emitter_helpers:
        return EMIT
    if cmd in ENV_DUMPERS:
        # `set` is the odd member: bare `set` dumps the shell variables, but
        # `set -- "$PAT"` ASSIGNS the positional parameters and writes nothing.
        # Grading every `set` a dumper flagged the assignment form (#1032
        # round 7 P2).  The other dumpers take no operand that changes this.
        if cmd == "set" and len(seg.words) > 1:
            return SAFE
        return EMIT
    # Ordered BEFORE SAFE_COMMANDS on purpose: `exit`, `return` and `shift`
    # are listed there as control words, and that listing is what made the
    # stderr diagnostic invisible.
    if cmd in NUMERIC_OPERAND_DIAGNOSTIC:
        return EMIT
    # `select value in LIST` prints LIST as a NUMBERED MENU on stderr before
    # it reads anything, so a credential in the list reaches a stream even
    # when the loop body does nothing and even with stdin closed.  It sat in
    # SAFE_COMMANDS beside `for` and `case`, which really are word-consuming
    # -- `select` is the one member of that group that echoes its words
    # (#1032 round 8 P1).
    if cmd == "select":
        return EMIT
    if cmd in SAFE_COMMANDS:
        return SAFE
    return SAFE  # an external command: see "does NOT catch" in the header


def _short_option_operand_has_ref(seg, name, option_letters):
    """Does a short option in `option_letters` receive credential `name`?

    Handles separate, attached and bundled spellings for every builtin that
    uses the ordinary short-option grammar: `read -rt "$PAT"`,
    `read -t"$PAT"`, and `mapfile -n"$PAT"`.  The earlier read-only helper
    both duplicated the command boundary and failed to see attached bundled
    operands because the expansion made literal reduction return None.
    """
    words = list(seg.words)
    command, _redir = resolve_command(seg)
    for command_idx, word in enumerate(words):
        lit = _unquote_command_word(word)
        if lit is not None and _basename(lit) == command:
            break
    else:
        return False
    words = words[command_idx + 1 :]
    all_operand_letters = SHORT_OPTION_OPERAND_LETTERS.get(
        command, frozenset(option_letters)
    )
    i = 0
    while i < len(words):
        w = words[i]
        lit = _unquote_command_word(w)
        has_ref = name in _iter_refs(w)
        if lit is None:
            # Only the literal prefix before the first expansion can contain
            # option letters.  Quotes around the attached operand are syntax,
            # not part of the option: `-rt"$PAT"` reduces to prefix `-rt`.
            cut = len(w)
            for marker in ("$", "`"):
                pos = w.find(marker)
                if pos >= 0:
                    cut = min(cut, pos)
            probe = re.sub(r"[\\'\"]", "", w[:cut])
        else:
            probe = lit
        if probe == "--":
            break
        if not probe.startswith("-") or probe.startswith("--"):
            break
        letters = probe[1:]
        if not letters:
            break
        consumed_operand = False
        for pos, letter in enumerate(letters):
            if letter not in all_operand_letters:
                continue
            # Everything after an argument-taking option letter is its
            # attached operand.  If the same word carries the reference, the
            # credential is part of that operand; otherwise a literal operand
            # is already attached and later words are not option arguments.
            if pos + 1 < len(letters):
                if letter in option_letters and has_ref:
                    return True
                consumed_operand = True
                break
            if letter in option_letters and has_ref:
                return True
            if i + 1 < len(words):
                if letter in option_letters and name in _iter_refs(words[i + 1]):
                    return True
                i += 2
            else:
                i += 1
            consumed_operand = True
            break
        if consumed_operand:
            if pos + 1 < len(letters):
                i += 1
            continue
        i += 1
    return False


def _test_numeric_operand(seg, name):
    """Is `name` beside a numeric operator in `test` or `[`?"""
    words = list(seg.words)
    for i, word in enumerate(words):
        if _unquote_command_word(word) not in TEST_NUMERIC_OPERATORS:
            continue
        for operand_idx in (i - 1, i + 1):
            if (
                0 <= operand_idx < len(words)
                and name in _iter_refs(words[operand_idx])
            ):
                return True
    return False


def reaches_output(ref, emitter_helpers):
    """Does this reference reach a stream?  Returns (bool, reason)."""
    if ref.in_error_word:
        # Decided BEFORE the command word, and deliberately ahead of the
        # assign-prefix branch too: `x=${UNSET:?$PAT}` is an assignment whose
        # EXPANSION writes to stderr and then exits, so asking what the
        # command does with the value is asking the wrong question.
        return True, (
            "the error word of a `${...:?...}` expansion, which bash itself "
            "writes to stderr when the variable is unset"
        )
    if ref.seg is not None and not ref.in_assign_prefix:
        rcmd, _rredir = resolve_command(ref.seg)
        numeric_options = NUMERIC_OPTION_LETTERS.get(rcmd)
        if numeric_options and _short_option_operand_has_ref(
            ref.seg, ref.name, numeric_options
        ):
            return True, (
                "the operand of a numeric `%s` option, which bash reproduces "
                "verbatim on stderr when it is not a number" % rcmd
            )
        if rcmd == "read" and _short_option_operand_has_ref(
            ref.seg, ref.name, frozenset({"p"})
        ):
            return True, (
                "the operand of `read -p`, which bash writes verbatim as a "
                "prompt when standard input is a terminal"
            )
        if rcmd in ("test", "[") and _test_numeric_operand(ref.seg, ref.name):
            return True, (
                "an operand of a numeric `%s` comparison, which bash "
                "reproduces verbatim on stderr when it is not an integer" % rcmd
            )
    if ref.in_assign_prefix:
        # `GH_TOKEN="$PAT" cmd ...` puts the value in the child's ENVIRONMENT.
        cmd, _ = resolve_command(ref.seg)
        if cmd == "printf":
            _args, _index, assigned, separate, _targets = _printf_assignment_options(ref.seg)
            if assigned and not separate:
                return True, (
                    "a credential-bearing assignment prefix on attached printf "
                    "assignment options, which may diagnose before printf runs"
                )
        if cmd in ENV_DUMPERS:
            return True, (
                "an env-prefix assignment handed to %s, which dumps the "
                "environment it was given" % cmd
            )
        return False, ""

    # A here-doc body belongs to the command that OPENED it, which may be in a
    # later segment (`true; cat <<EOF`).  From there it walks out exactly like
    # any other reference, so a captured here-doc gets the same shield a
    # captured `printf` does.
    # A reference that IS body text starts at the owner.  A reference inside a
    # command substitution WITHIN that body starts at its own segment -- the
    # substitution runs first, and the body is only where its output lands --
    # and walks out to the owner through `parent_is_capture`.  Both carry the
    # here-doc note, which is what makes the owner an emitter on the way out.
    seg = ref.heredoc_owner if ref.heredoc_owner is not None else ref.seg
    note = "interpolating here-doc body" if ref.in_heredoc_body else None

    hops = 0
    via_stdin = False
    # Set while the walk is standing on the segment a `( ... )` SUBSHELL was
    # written in.  The value is already on that segment's standard output -- a
    # subshell's standard output IS the enclosing command's -- so it is not
    # re-graded as an emitter; it is asked only where its own output goes.
    # `emitter` keeps the command that put the value there, for the message.
    from_subshell = False
    # Redirections the value has ALREADY passed through inside a `( )`, kept
    # in the two shapes the two hops ask for: `escaped_any` is what the
    # capture hop tests (any output redirection, the `_OUT_REDIR_RE` reading
    # #1042 tracks), `escaped_fd1` what the pipeline hop tests (fd 1 only).
    # In `v=$( ( printf '%s' "$PAT" >&2 ) )` the redirection sits on the
    # printf and the capture it escapes is two segments further out, so
    # without this the hop out of the subshell would drop it.
    escaped_any = False
    escaped_fd1 = False
    emitter = None
    while seg is not None and hops < 32:
        hops += 1
        cmd, has_out_redir = resolve_command(seg)
        kind = classify(seg, emitter_helpers)
        if kind == OPAQUE:
            return True, "command word could not be resolved (%s)" % (
                "unresolvable" if cmd is UNRESOLVED else cmd
            )
        # A redirection the value passed through inside a `( )` counts here
        # exactly as one written on this segment would: when this segment is
        # a subshell's WRAPPER, the redirection in `( ... ) >&2` is parked on
        # it by the lexer and is the subshell's own.  Each hop below keeps its
        # own reading -- `_OUT_REDIR_RE` for the capture, fd 1 for the
        # pipeline -- so the subshell spelling and the bare spelling of a line
        # get the same verdict rather than a third one.
        has_out_redir = has_out_redir or escaped_any
        stdout_moved = redirects_stdout(seg) or escaped_fd1
        # `via_stdin` and `from_subshell` are exclusive by construction: each
        # hop below clears the other, because a value cannot arrive on a
        # segment's standard input AND already be on its standard output.
        if via_stdin:
            # The value arrived on THIS segment's standard input, through a
            # pipe.  `echo` and `printf` write their ARGUMENTS and discard
            # stdin, so being an emitter says nothing here; only a command
            # that writes its stdin puts the value back on a stream.
            #
            # What any OTHER command does with a value handed to its stdin is
            # the same unmodelled question as a value handed to it as an
            # argument (`curl -H "...: $PAT"`), and the here-string spelling
            # of it -- `grep -qF x <<< "$PAT"` -- is already clean.  Flagging
            # the pipe spelling alone made the gate disagree with itself and
            # redded the canonical secure hand-off (`gh auth login
            # --with-token`, `docker login --password-stdin`); see the
            # "does NOT catch" list, which now names the whole class.
            if cmd is None:
                if not [w for w in seg.words if w not in ("{", "}")]:
                    # Not a simple command: a `{ ...; }` group, a `( ... )`
                    # subshell, or a `|&` consumer.  WHICH command inside the
                    # group reads the pipe is a dataflow question a
                    # single-line source-text scanner cannot answer, so this
                    # fails CLOSED.  Declared in KNOWN_BROADER.
                    return True, _why(
                        note,
                        "piped into a group whose consumer cannot be resolved",
                    )
                # An assignment-only consumer (`... | v=1`) runs no command
                # and writes nothing.
                return False, ""
            if cmd not in STDIN_ECHOERS:
                return False, ""
            kind = EMIT
            if note is None:
                note = "piped standard input"
        # `cat`/`tee` write their standard input, so a here-doc body or a
        # here-string handed to one is an emission by the same rule.
        elif kind != EMIT and cmd in STDIN_ECHOERS:
            if note is not None or "<<<" in seg.words:
                kind = EMIT
                if note is None:
                    note = "here-string"
        if from_subshell:
            # Not re-graded: `( ... )` is the command here, and the value is
            # on its standard output already.  The wrapper segment holds only
            # the subshell's redirections (and, in front of the `(`, a
            # reserved word such as `then`), so asking whether IT is an
            # emitter would answer about a segment that runs nothing.
            pass
        elif kind != EMIT:
            return False, ""
        else:
            emitter = cmd or emitter
        if seg.pipe_to is not None:
            # The value goes into the next segment's stdin rather than to a
            # terminal -- unless a redirection moves fd 1 somewhere the pipe
            # does not reach, which is the same escape the capture shield
            # below measures (`printf '%s' "$PAT" >&2 | grep -q x` reaches
            # the terminal on stderr).
            if stdout_moved:
                return True, _why(
                    note,
                    "%s whose output redirection escapes the pipeline"
                    % (cmd or emitter or "output command"),
                )
            tee_files = tee_file_operands(seg)
            if tee_files:
                # `tee FILE` is a fork, not a hop: the pipe carries the value
                # onward AND the file receives it.  Following only the pipe
                # graded the consumer and never saw the write.
                return True, _why(
                    note, "tee, which also writes the value to %s" % tee_files[0]
                )
            seg = seg.pipe_to
            via_stdin = True
            from_subshell = False
            escaped_any = False
            escaped_fd1 = False
            continue
        if seg.parent_is_subshell and seg.parent is not None:
            # Out of the subshell and onto the ENCLOSING command's stdout.
            # Nothing is captured here and nothing is decided here: the
            # wrapper segment is where the subshell's own redirection, pipe
            # and capture status live, so the next turn of this loop reads
            # them off it -- which is what keeps `( ... ) >&2` inside `$( )`
            # an escape and `( ... )` inside `$( )` a capture, from the same
            # rule rather than from two.  A redirection ALREADY passed --
            # inside the parens, or on a nested `( )` -- travels out with the
            # value, because the parens do not undo it: dropping it here is
            # what let `v=$( ( printf '%s' "$PAT" >&2 ) )` read clean.
            seg = seg.parent
            via_stdin = False
            from_subshell = True
            escaped_any = has_out_redir
            escaped_fd1 = stdout_moved
            continue
        if seg.parent_is_capture and seg.parent is not None:
            if has_out_redir:
                return True, _why(
                    note, "%s inside $( ), where an output redirection "
                    "escapes the capture"
                    % (cmd or emitter or "output command"),
                )
            seg = seg.parent
            via_stdin = False
            from_subshell = False
            escaped_any = False
            escaped_fd1 = False
            note = note  # the note travels out with the reference
            continue
        return True, _why(note, cmd or emitter or "output command")
    return True, "expansion nesting too deep to resolve"


def _why(note, base):
    return "%s written by %s" % (note, base) if note else base


# ==========================================================================
# In-file message-helper discovery
# ==========================================================================

def _find_compound_close(text, open_idx, bracket_span=False):
    """Return the matching close index for a brace group or subshell body.

    Only the heredoc legacy-arithmetic inventory opts into bracket spans;
    default callers retain the existing brace/subshell reading.

    The caller hands this function text whose here-doc body lines have already
    been blanked.  Counting over the raw source treated braces and parentheses
    in here-doc DATA as shell structure, which could end a real function body
    early even after the discovery regex stopped matching fake definitions in
    that data.
    """
    try:
        return _find_compound_close_exact(text, open_idx, bracket_span)
    except _ExactReadUnavailable:
        return _find_compound_close_legacy(text, open_idx, bracket_span)


def _find_compound_close_exact(text, open_idx, bracket_span=False):
    opener = text[open_idx]
    closer = "]" if bracket_span else ("}" if opener == "{" else ")")
    depth = 0
    i = open_idx
    n = len(text)
    quotes = []
    while i < n:
        c = text[i]
        if quotes and quotes[-1] == "'":
            if c == "'":
                quotes.pop()
            i += 1
            continue
        if c == "\\":
            i += 2
            continue
        if c == "#" and not quotes and (i == 0 or text[i - 1] in _WORD_BREAK_BEFORE_COMMENT):
            eol = text.find("\n", i)
            i = n if eol == -1 else eol
            continue
        if c == "'" and not quotes:
            quotes.append("'")
            i += 1
            continue
        if c == '"':
            if quotes:
                quotes.pop()
            else:
                quotes.append('"')
            i += 1
            continue
        if quotes:
            end = _double_quoted_construct_end(text, i)
            i = i + 1 if end is None else end
            continue
        if c == opener:
            depth += 1
        elif c == closer:
            depth -= 1
            if depth == 0:
                return i
        i += 1
    return None


def _find_compound_close_legacy(text, open_idx, bracket_span=False):
    opener = text[open_idx]
    closer = "]" if bracket_span else ("}" if opener == "{" else ")")
    depth = 0
    i = open_idx
    n = len(text)
    quotes = []
    while i < n:
        c = text[i]
        if quotes and quotes[-1] == "'":
            if c == "'":
                quotes.pop()
            i += 1
            continue
        if c == "\\":
            i += 2
            continue
        if c == "#" and not quotes and (i == 0 or text[i - 1] in _WORD_BREAK_BEFORE_COMMENT):
            eol = text.find("\n", i)
            i = n if eol == -1 else eol
            continue
        if c == "'":
            quotes.append("'")
            i += 1
            continue
        if c == '"':
            if quotes and quotes[-1] == '"':
                quotes.pop()
            else:
                quotes.append('"')
            i += 1
            continue
        if quotes:
            i += 1
            continue
        if c == opener:
            depth += 1
        elif c == closer:
            depth -= 1
            if depth == 0:
                return i
        i += 1
    return None


_FUNC_DEF_RE = re.compile(
    r"(?m)(?:^|(?<=[;&|(){}!])|(?<=\bif)|(?<=\belif)|(?<=\bwhile)"
    r"|(?<=\buntil)|(?<=\bthen)|(?<=\bdo)|(?<=\belse)|(?<=\bin)"
    r"|(?<=\btime))[ \t]*(?P<keyword>function[ \t]+)?"
    r"(?P<name>[A-Za-z_][A-Za-z0-9_:.-]*)[ \t]*"
    r"(?(keyword)(?:\([ \t]*\)|(?=[ \t\n]))|\([ \t]*\))"
    r"(?:[ \t\n]|#[^\n]*\n)*"
    r"(?P<opener>\{|\((?![ \t]*\)))"
)


def _mask_heredoc_body_lines(text, lx=None):
    """Blank here-doc DATA, retaining already-lexed executable child source."""
    if lx is None:
        lx = Lexer(text)
    masked = list(text)
    line_starts = [0]
    for i, c in enumerate(text):
        if c == "\n":
            line_starts.append(i + 1)
    for hd in lx.heredocs:
        for line, raw in hd.body_lines:
            start = line_starts[line - 1]
            masked[start : start + len(raw)] = " " * len(raw)
    # An interpolating here-doc runs its substitutions. Restore their source,
    # recursively masking the child's own here-doc DATA; quotes and comments
    # retain the child Lexer's original offsets for the iterator's exclusions.
    for start, sub in lx.function_source_children:
        structural = _mask_heredoc_body_lines(sub.text, sub)
        masked[start : start + len(structural)] = structural
    return "".join(masked)


def _iter_function_definitions(text):
    """Yield each recognized function definition as (match, name, body).

    Function definitions are valid at every command position, including a
    case arm after `)`, a brace group after `{`, and condition positions after
    `if` / `while` / `until` / `!` / `time`.  Keep that grammar in one place:
    three copied regexes drifted together and still omitted those positions,
    letting a positional-emitting helper defined there read as an unknown safe
    command (#1032 external review).

    A completed name() or function-keyword header may precede its brace or
    subshell body after whitespace or comments. Empty header parentheses are
    never a body opener; the match ends at the actual opener for both consumers.
    """
    # Function-shaped here-doc DATA is not shell structure.  Discover against
    # an offset-preserving masked copy, then return the body from the original
    # source so a genuine function's own here-doc remains available to helper
    # analysis.
    lx = Lexer(text)
    structural = _mask_heredoc_body_lines(text, lx)
    for m in _FUNC_DEF_RE.finditer(structural):
        if (
            m.start("name") in lx.quoted_data_offsets
            or m.start("name") in lx.comment_offsets
        ):
            continue
        name = m.group("name")
        if name in RESERVED_WORDS:
            continue
        open_idx = m.end() - 1
        close_idx = _find_compound_close(structural, open_idx)
        if close_idx is not None:
            yield m, name, text[open_idx + 1 : close_idx]


def _printf_callback_changes_lookup(seg):
    """Withhold attached eligibility for mapfile/readarray callback options.

    Read only the finite builtin short-option prefix. Options taking an argument
    consume the cluster remainder or the next word; a C in that data is not -C.
    This does not change the broader deferred-source reader or output walk.
    """
    cmd, _redir = resolve_command(seg)
    if cmd not in DEFERRED_SHELL_OPTIONS or seg._cmd_index is None:
        return False
    args = list(_command_arguments(seg.words, seg._cmd_index + 1))
    i = 0
    while i < len(args):
        raw, literal = args[i]
        if literal is None or "$'" in raw or _command_word_expands(raw):
            return True  # An unresolved option can request a callback.
        if literal == "--" or literal == "-" or not literal.startswith("-"):
            return False
        cluster = literal[1:]
        for j, option in enumerate(cluster):
            if option == "C":
                return True  # Callback execution/restoration is not proved.
            if option in "cdnOsu":
                if j + 1 == len(cluster):
                    i += 1  # Its argument is the next word, even if option-like.
                break
            if option != "t":
                return True  # Unsupported clusters do not prove lookup safety.
        i += 1
    return False



def discover_emitter_helpers(text):
    """Names with any recognized body writing their positionals VERBATIM."""
    bodies = {}
    # NOT `^[ \t]*`.  A function definition is valid at any COMMAND POSITION,
    # not only at the start of a physical line: `true; log(){ echo "$1"; }`
    # defines `log`, and the anchored form never discovered it, so the later
    # `log "$PAT"` graded as an unknown external command and read clean
    # (#1032 round 6 P1).  The lookbehind keeps `m.start()` on the NAME, so
    # the `function`-form check below still sees the head it expects.
    # Textual order cannot establish which definitions executed (#1467).
    # Preserve every body, including definitions after calls or in false branches.
    for _match, name, body in _iter_function_definitions(text):
        bodies.setdefault(name, []).append(body)

    # Lex each body ONCE.  What a body does never changes between rounds; only
    # the `helpers` set a call inside it is graded against does, and that is
    # what the fixed point below iterates.
    lexed = [(name, body, Lexer(body))
             for name, definitions in bodies.items() for body in definitions]

    # A local printf or passthrough-prefix definition invalidates the new
    # attached-option builtin exemption even for a non-emitting body.
    # Retain the parent scanner's conservative verdict on that spelling.
    # `enable` changes builtin availability. Without execution/state dataflow
    # any such operation makes the attached printf exemption uncertain; even
    # a later apparent re-enable is not proof it executed in this shell.
    availability_changed = False
    binding_names = {"printf"} | PASSTHRU
    for line in Lexer(text).logical:
        for seg in line.segments:
            cmd = resolve_command(seg)[0]
            if seg._function_binding is not None:
                position, word = seg._function_binding
                # Bare prefix names have no resolved invocation index: the
                # resolver consumes them as wrappers. A declaration at the
                # segment's command position still shadows that prefix.
                at_command = position == seg._cmd_index or (
                    seg._cmd_index is None
                    and all(w in RESERVED_WORDS for w in seg.words[:position])
                )
                if at_command and _unquote_command_word(word) in binding_names:
                    availability_changed = True
            # A function-keyword header can put its body on the next line.
            # Record only the uncertain binding using existing command
            # positions; general helper body-span discovery stays unchanged.
            limit = seg._cmd_index if seg._cmd_index is not None else len(seg.words)
            for i, word in enumerate(seg.words[:limit]):
                if (word == "function" and i + 1 < len(seg.words)
                        and _unquote_command_word(seg.words[i + 1]) in binding_names):
                    availability_changed = True
            if _printf_callback_changes_lookup(seg):
                # Existing deferred callbacks can change lookup before printf.
                availability_changed = True
            if cmd in OPAQUE_COMMANDS | {"enable", "alias", UNRESOLVED}:
                # Opaque setup or aliases may change lookup indirectly. No
                # execution-state model proves builtin availability afterward.
                availability_changed = True
            elif cmd in ("declare", "typeset", "local") and seg._cmd_index is not None:
                # A plain variable can name an arithmetic array target through
                # a nameref, or validate its value through an integer attribute.
                # Do not infer its runtime binding or restoration.
                for raw, literal in _command_arguments(seg.words, seg._cmd_index + 1):
                    if literal is None or "$'" in raw or _command_word_expands(raw):
                        availability_changed = True
                        break
                    if literal == "--" or not literal.startswith("-"):
                        break
                    if set(literal[1:]) & {"i", "n"}:
                        availability_changed = True
    shadowed = "printf" in bodies or any(name in PASSTHRU for name in bodies)
    helpers = {"printf"} if shadowed or availability_changed else set()
    # A FIXED POINT, not a fixed number of rounds.  Each round can promote at
    # most one link of a call chain, so a chain longer than the round budget
    # left its outermost helper undiscovered -- `a` calls `b` calls `c` calls
    # `d` calls `echo "$1"` needs four (#1032 F6).  The set only ever grows and
    # is bounded by the number of functions in the file, so this terminates.
    while True:
        grew = False
        for name, body_text, lx in lexed:
            if name in helpers:
                continue
            emits = False
            for ll in lx.logical:
                for seg in ll.segments:
                    cmd, _redir = resolve_command(seg)
                    if classify(seg, helpers) != EMIT:
                        # `cat`/`tee` write their STANDARD INPUT, so a helper
                        # handing a positional to one on a here-string writes
                        # it just as surely as `echo "$1"` does.  Only the
                        # ARGUMENT spelling was graded, so
                        # `log() { cat <<< "$1"; }` read clean (#1032 F5).
                        #
                        # Not when THIS FILE redefines the name: a local
                        # `cat() { :; }` is what the here-string is handed to,
                        # and what a function does with its standard input is
                        # the limit already declared for
                        # `indirect-pipe-into-stdin-echoing-helper`.
                        if not (
                            cmd in STDIN_ECHOERS
                            and cmd not in bodies
                            and "<<<" in seg.words
                        ):
                            continue
                    for w in seg.words:
                        if _word_has_verbatim_positional(w):
                            emits = True
                            break
                    if emits:
                        break
                if emits:
                    break
            # A helper body can put a positional on a stream without naming
            # an emitter at all: BASH writes a `${VAR:?WORD}` error word
            # itself, and under xtrace it writes every expanded command.  This
            # loop only promoted segments classified EMIT, so
            # `leak(){ : "${UNSET:?$1}"; }` and `leak(){ set -x; : "$1"; }`
            # both read clean (#1032 round 8 P1).  Graded on the body TEXT,
            # which is what those two mechanisms actually act on.
            if not emits:
                for a, b in _error_word_spans(body_text):
                    if _word_has_verbatim_positional(body_text[a:b]):
                        emits = True
                        break
                if not emits and _text_enables_xtrace(body_text) \
                        and _word_has_verbatim_positional(body_text):
                    emits = True
            # A nested or direct HD uses the same bounded admission rule.
            if not emits:
                emits = any(_heredoc_has_positional(hd, helpers) for hd in lx.heredocs)
            if emits:
                helpers.add(name)
                grew = True
        if not grew:
            break
    return frozenset(helpers)


def _heredoc_has_positional(hd, emitter_helpers, _depth=0):
    """Shared HD admission; child source consumes the existing one-hop budget."""
    if not hd.interpolating:
        return False
    cmd, _ = resolve_command(hd.owner)
    body = _heredoc_continuation_text("\n".join(raw for _lno, raw in hd.body_lines))
    if cmd in STDIN_ECHOERS or classify(hd.owner, emitter_helpers) == OPAQUE:
        if _word_has_verbatim_positional(body, in_heredoc=True, _depth=_depth):
            return True
    else:
        # Direct stdin DATA is inert for argument emitters. Actual source
        # and diagnostics retain the existing independent admission.
        for inner, start, _end in _find_substitutions(
                body, quotes_are_literal=True, include_arithmetic=True):
            if body[start] == "`":
                inner = _backtick_positional_source(inner)
            positional = (_word_has_verbatim_positional(inner, in_heredoc=True, _depth=_depth)
                          if body.startswith(("$[", "$((", "${"), start)
                          else _heredoc_substitution_has_positional(inner, _depth))
            if positional:
                return True
    for start, end in _error_word_spans(body, in_heredoc=True):
        if _word_has_verbatim_positional(body[start:end], in_heredoc=True, _depth=_depth):
            return True
    return False


def _backtick_positional_source(body):
    """Remove the backtick source layer before the ordinary positional read."""
    return re.sub(
        r"\\([$`\\]|\n)",
        lambda m: "" if m.group(1) == "\n" else m.group(1),
        body,
    )


def _heredoc_substitution_has_positional(body, _depth=0):
    """Inventory actual source within one shared HD/deferred child hop.

    Keep ordinary source checking first, including its conservative legacy
    reading. Only discovered-HD and deferred child inventory consume the
    existing budget; deeper source is not claimed uniformly inert or covered.
    """
    if _word_has_verbatim_positional(body):
        return True
    lx = Lexer(body)
    # Lexer segments retain executable quote/escape context and omit comments
    # and inert HD data. Rejoin words for legacy arithmetic split by spaces;
    # only recognized arithmetic operands receive arithmetic quote semantics.
    for ll in lx.logical:
        for seg in ll.segments:
            executable = " ".join(seg.words)
            for operand, start, _end in _find_substitutions(executable, include_arithmetic=True):
                if executable.startswith(("$[", "$((", "${"), start):
                    if _word_has_verbatim_positional(operand, in_heredoc=True, _depth=_depth):
                        return True
    if _depth >= _DEFERRED_SHELL_DEPTH:
        return False
    for hd in lx.heredocs:
        if _heredoc_has_positional(hd, set(), _depth + 1):
            return True
    for ll in lx.logical:
        for seg in ll.segments:
            for inner in _deferred_shell_operands(seg):
                if _heredoc_substitution_has_positional(inner, _depth + 1):
                    return True
    return False


def _heredoc_continuation_text(body):
    """Apply the existing unquoted-heredoc continuation rule once."""
    return re.sub(
        r"\\([$`\\]|\n)",
        lambda m: "" if m.group(1) == "\n" else m.group(0),
        body,
    )


def _word_has_verbatim_positional(w, in_heredoc=False, _depth=0):
    """True when the word expands a positional parameter's VALUE.

    Single-quoted text never expands, `${1:+set}` is a constant alternate and
    `${#1}` is a length and exact `${1@a}` is attributes-only -- a helper uses the same redacted
    forms the check documents for callers.  Inside double quotes an
    apostrophe is literal (#1494); see `_ExactReadUnavailable` for how that
    reading falls back.

    In an interpolating here-doc, quotes are literal and backslash quotes
    only dollar, backtick, backslash and newline. Remove unescaped continued
    newlines before the shared positional decision; an escaped backslash
    pair stays intact and cannot turn the following newline into a join.
    Actual backtick bodies have their separate source-escape layer removed
    before recursive ordinary reading; modern substitutions do not. Actual
    substitution bodies reuse the literal deferred-source reader within its
    existing one-hop bound, without interpreting general parameter flow.
    """
    if in_heredoc:
        w = _heredoc_continuation_text(w)
    try:
        return _word_has_verbatim_positional_exact(w, in_heredoc, _depth)
    except _ExactReadUnavailable:
        return _word_has_verbatim_positional_legacy(w, in_heredoc, _depth)


def _word_has_verbatim_positional_exact(w, in_heredoc=False, _depth=0):
    i = 0
    n = len(w)
    in_double = False
    while i < n:
        c = w[i]
        if (c == "\\" and i + 1 < n
                and (not in_heredoc or w[i + 1] in "$`\\\n")):
            i += 2
            continue
        if c == '"' and not in_heredoc:
            in_double = not in_double
            i += 1
            continue
        if c == "'" and not in_double and not in_heredoc:
            j = w.find("'", i + 1)
            i = n if j == -1 else j + 1
            continue
        if ((in_double or in_heredoc)
                and (c == "`" or (c == "$" and w[i + 1 : i + 2] == "("))):
            # The body still expands: grade it as a word of its own.
            end = _double_quoted_construct_end(w, i)
            closed = c != "`" or (end - 1 > i and w[end - 1] == "`")
            lo = i + 1 if c == "`" else i + 2
            body = w[lo : end - 1 if closed else end]
            if c == "`" and in_heredoc:
                body = _backtick_positional_source(body)
            if (_heredoc_substitution_has_positional(body, _depth) if in_heredoc
                    else _word_has_verbatim_positional_exact(body)):
                return True
            i = end
            continue
        if (in_double or in_heredoc) and c == "$" and w[i + 1 : i + 2] == "{":
            _simple_parameter_end(w, i)  # raises on a word it cannot read
        if c == "$":
            if i + 1 < n and w[i + 1] == "{":
                j = i + 2
                if j < n and w[j] in "#!":
                    i += 2
                    continue
                m = re.match(r"([1-9][0-9]*|[@*])", w[j:])
                if m:
                    rest = w[j + m.end() : j + m.end() + 2]
                    if (rest[:1] == "+" or rest[:2] == ":+"
                            or (rest == "@a" and w[j + m.end() + 2 : j + m.end() + 3] == "}")):
                        i = j + m.end()
                        continue
                    return True
                i += 2
                continue
            m = re.match(r"([1-9][0-9]*|[@*])", w[i + 1 :])
            if m:
                return True
        i += 1
    return False


def _word_has_verbatim_positional_legacy(w, in_heredoc=False, _depth=0):
    i = 0
    n = len(w)
    while i < n:
        c = w[i]
        if (c == "\\" and i + 1 < n
                and (not in_heredoc or w[i + 1] in "$`\\\n")):
            i += 2
            continue
        if c == "'" and not in_heredoc:
            j = w.find("'", i + 1)
            i = n if j == -1 else j + 1
            continue
        if c == "`" and in_heredoc:
            end = _skip_backtick(w, i)
            closed = end - 1 > i and w[end - 1] == "`"
            body = _backtick_positional_source(w[i + 1 : end - 1 if closed else end])
            if _heredoc_substitution_has_positional(body, _depth):
                return True
            i = end
            continue
        if c == "$":
            if i + 1 < n and w[i + 1] == "{":
                j = i + 2
                if j < n and w[j] in "#!":
                    i += 2
                    continue
                m = re.match(r"([1-9][0-9]*|[@*])", w[j:])
                if m:
                    rest = w[j + m.end() : j + m.end() + 2]
                    if (rest[:1] == "+" or rest[:2] == ":+"
                            or (rest == "@a" and w[j + m.end() + 2 : j + m.end() + 3] == "}")):
                        i = j + m.end()
                        continue
                    return True
                i += 2
                continue
            m = re.match(r"([1-9][0-9]*|[@*])", w[i + 1 :])
            if m:
                return True
        i += 1
    return False


# ==========================================================================
# File-level scan
# ==========================================================================


class Finding:
    __slots__ = ("path", "line", "name", "reason")

    def __init__(self, path, line, name, reason):
        self.path = path
        self.line = line
        self.name = name
        self.reason = reason

    def __str__(self):
        return "%s:%d: %s reaches output via %s" % (
            self.path,
            self.line,
            self.name,
            self.reason,
        )


# Command words whose LITERAL operand is shell source the shell runs LATER.
# Quoting inside such an operand is quoting of the TEXT, not of an expansion:
# `trap 'echo "$GH_TOKEN"' EXIT` stores the single-quoted body and expands
# `$GH_TOKEN` when the trap fires, so bash prints the credential while the
# lexer -- correctly, for ordinary text -- reported no reference at all and
# `--scan` returned PASS (#1032 round 4 P1).  This is the same relationship an
# interpolating here-doc body has with its opener, and it is handled the same
# way: the literal is re-read AS SHELL.
DEFERRED_SHELL_COMMANDS = frozenset({"trap", "eval"})
# Commands that take deferred shell in a NAMED OPTION rather than in every
# operand.  `mapfile -C CALLBACK` / `readarray -C CALLBACK` EVALUATE the
# callback, so `mapfile -C 'echo "$PAT"' -c 1 v < <(...)` prints the
# credential (#1032 round 7 P1).  Only the option's own argument is shell --
# the array name and the other operands are not -- so these are kept apart
# from DEFERRED_SHELL_COMMANDS, whose operands are all shell.
DEFERRED_SHELL_OPTIONS = {
    "mapfile": "-C",
    "readarray": "-C",
}
# One hop.  A `trap 'eval "..."' EXIT` gets its inner eval graded; a third
# level is a declared miss rather than an unbounded recursion, and the bound
# is here rather than implied by the call graph.
_DEFERRED_SHELL_DEPTH = 1

# Words that turn bash's xtrace on and off.  With xtrace active bash writes
# EVERY expanded command to stderr, so a credential reference reaches a stream
# no matter which command holds it -- `set -x; : "$GH_TOKEN"` puts the value
# on stderr through `+ : <value>` while `:` is the safest command word there
# is (#1032 round 4 P1).  This is shell STATE, not a property of the line, so
# it is tracked across the file in source order rather than decided per
# segment.  `set +x` turns it back off and is tracked too.
_XTRACE_ON = ("-x", "-o", "--xtrace")
_XTRACE_OFF = ("+x", "+o")


def _deferred_shell_operands(seg):
    """LITERAL operands of a `trap` / `eval` segment, as shell source text."""
    cmd, _redir = resolve_command(seg)
    if cmd == "printf" and seg._cmd_index is not None:
        out = []
        for raw, literal in _command_arguments(seg.words, seg._cmd_index + 1):
            if literal == "-v":
                return []  # Keep the prior separate-option scope unchanged.
            if literal is None or not literal.startswith("-v") or len(literal) == 2:
                break
            target = literal[2:]
            if not _printf_text_target(raw, target):
                # Indexed targets can evaluate even single-quoted shell text.
                # Reuse the existing bounded reader, not an execution model.
                out.append(target)
        return out
    if cmd in DEFERRED_SHELL_OPTIONS and seg._cmd_index is not None:
        # Bash short options consume their own cluster remainder or the next
        # word. A C in that value is data, and operands after -- or the array
        # name are not callback options (#1450).
        args = list(_command_arguments(seg.words, seg._cmd_index + 1))
        out = []
        i = 0
        uncertain_prefix = False
        final_callback_certain = True
        while i < len(args):
            _raw, literal = args[i]
            if literal is None:
                # It might be a flag, a value-taking option or the array name.
                # Preserve known later callbacks rather than infer a clean path.
                uncertain_prefix = True
                final_callback_certain = False
                i += 1
                continue
            if literal == "--" or literal == "-" or not literal.startswith("-"):
                if not uncertain_prefix:
                    break
                i += 1
                continue
            cluster = literal[1:]
            for j, option in enumerate(cluster):
                if option in SHORT_OPTION_OPERAND_LETTERS[cmd]:
                    value = cluster[j + 1:]
                    if not value:
                        value = args[i + 1][1] if i + 1 < len(args) else None
                        if not uncertain_prefix:
                            i += 1
                    if option == "C":
                        if value is None:
                            final_callback_certain = False
                        else:
                            out.append(value)
                    break
                if option != "t":
                    if not uncertain_prefix:
                        return out  # Unsupported option prevents later callbacks.
                    break
            i += 1
        # Only the last C is effective when its option sequence is proven.
        # Unknown values/prefixes retain the prior per-known-literal fallback.
        return out[-1:] if final_callback_certain else out
    if cmd not in DEFERRED_SHELL_COMMANDS:
        return []
    out = []
    seen_command_word = False
    for w in seg.words:
        lit = _unquote_command_word(w)
        if lit is None:
            continue
        if not seen_command_word:
            if _basename(lit) == cmd:
                seen_command_word = True
            continue
        # A `trap` signal name (`EXIT`, `USR1`, `2`) is not shell source, but
        # grading it as such costs nothing: it holds no credential reference.
        out.append(lit)
    return out


def _segment_sets_xtrace(seg):
    """Return True / False to set xtrace state, or None to leave it alone."""
    cmd, _redir = resolve_command(seg)
    if cmd not in ("set", "shopt") or seg._cmd_index is None:
        return None
    lits = [literal for _raw, literal in
            _command_arguments(seg.words, seg._cmd_index + 1)]
    if cmd == "shopt":
        flags = set()
        unknown_flags = False
        i = 0
        while i < len(lits):
            word = lits[i]
            if word == "--":
                i += 1
                break
            if word is None:
                if "u" in flags:
                    return None  # A preceding literal unset cannot enable.
                # The word may supply flags or start the option-name list.
                unknown_flags = True
                i += 1
                continue
            if word == "-" or not word.startswith("-"):
                break  # A lone dash is an option name, not a flag bundle.
            if set(word[1:]) - set("opqsu"):
                return True if unknown_flags else None
            flags.update(word[1:])
            i += 1
        # Only enabling forms are added. Query/disable modes never acquire
        # new disable credit; the existing logical-line asymmetry remains.
        if unknown_flags:
            return True  # Missing enabling flags/names cannot be ruled out.
        if {"s", "o"} <= flags and "u" not in flags:
            return True if "xtrace" in lits[i:] or None in lits[i:] else None
        return None
    # Finite names shared by installed Bash 5.3/macOS and 5.2/Linux help.
    # They prove only a literal named operand, never runtime option values.
    named_options = {
        "allexport", "braceexpand", "emacs", "errexit", "errtrace",
        "functrace", "hashall", "histexpand", "history", "ignoreeof",
        "interactive-comments", "keyword", "monitor", "noclobber", "noexec",
        "noglob", "nolog", "notify", "nounset", "onecmd", "physical",
        "pipefail", "posix", "privileged", "verbose", "vi", "xtrace",
    }
    short_options = set("abefhkmnptuvxBCEHPTo")
    state = None
    uncertain = False
    i = 0
    while i < len(lits):
        a = lits[i]
        if a is None:
            # The unresolved word itself may enable tracing or stop parsing.
            # Retain possible enablement; later disable words are not proof.
            state = True
            uncertain = True
            i += 1
            continue
        if a == "--":
            break  # Positional input does not prove an option.
        if a in ("-o", "+o"):
            nxt = lits[i + 1] if i + 1 < len(lits) else None
            if nxt is None:
                if i + 1 < len(lits):
                    state = True  # An actual unresolved operand, not a query.
                    uncertain = True
                # Preserve the parent's next-literal named enable evidence:
                # an unresolved word may expand to another option, not a name.
                j = i + 1
                while j < len(lits) and lits[j] is None:
                    j += 1
                later = lits[j] if j < len(lits) else None
                if later is not None and not later.startswith(("-", "+")):
                    if a == "-o" and later == "xtrace":
                        state = True
                    i = j + 1  # Keep the parent's named-operand boundary.
                    continue
                i += 1
                continue
            if nxt.startswith(("-", "+")):
                i += 1  # No named operand; keep the following option visible.
                continue
            if nxt not in named_options:
                return state  # An invalid name stops before later disables.
            if nxt == "xtrace" and (a == "-o" or not uncertain):
                state = a == "-o"
            i += 2
            continue
        if a == "--xtrace":
            state = True
        elif a.startswith("-") and not a.startswith("--"):
            if "x" in a[1:]:
                state = True  # Preserve legacy conservative short-x evidence.
            operand_i = i + 1
            for letter in a[1:]:
                if letter not in short_options:
                    return state  # Keep any enable applied before the error.
                if letter != "o":
                    continue
                nxt = lits[operand_i] if operand_i < len(lits) else None
                if nxt is None:
                    if operand_i < len(lits):
                        state = True
                        uncertain = True
                        operand_i += 1
                elif not nxt.startswith(("-", "+")):
                    if nxt == "xtrace":
                        state = True
                    if nxt not in named_options:
                        return state
                    operand_i += 1
            i = operand_i
            continue
        elif a.startswith("+"):
            operand_i = i + 1
            for letter in a[1:]:
                if letter not in short_options:
                    return state
                if letter == "o":
                    nxt = lits[operand_i] if operand_i < len(lits) else None
                    if nxt is None:
                        if operand_i < len(lits):
                            state = True
                            uncertain = True
                            operand_i += 1
                    elif not nxt.startswith(("-", "+")):
                        if nxt not in named_options:
                            return state  # A following +x has not run.
                        operand_i += 1  # No new bundled +o disable credit.
                elif letter == "x" and not uncertain:
                    state = False  # Only after preceding options succeeded.
            i = operand_i
            continue
        else:
            break  # The first ordinary operand ends set option processing.
        i += 1
    return state


_ALIAS_RE = re.compile(r"^([A-Za-z_][A-Za-z0-9_:.-]*)=(.*)$", re.S)


def _alias_emitters(lx, helpers):
    """Alias names that resolve to an emitter, when `expand_aliases` is on.

    `shopt -s expand_aliases` + `alias leak=echo` makes `leak "$PAT"` an
    `echo`, and the classifier read `leak` as an unknown external command and
    called it safe (#1032 round 6 P1).  An alias is exactly the relationship
    an emitter HELPER already has with its call sites, so the names are folded
    into that same set rather than given a second mechanism.

    Two gates, both of them bash's own rules rather than caution:

      * `expand_aliases` must be enabled.  Bash does not expand aliases in a
        non-interactive shell without it, which is why `alias leak=echo`
        alone leaves the call a genuine unknown command -- measured, and a
        MUST_NOT_FLAG case.
      * the definition must be on an EARLIER logical line than the use.  Bash
        expands aliases when it READS a line, so a definition and a use on
        the same line do not connect -- also measured, also a case.

    Only a LITERAL target counts.  `alias leak="$cmd"` names something this
    scanner cannot read, and it is left to the unknown-command limit rather
    than guessed at.
    """
    enabled_at = None
    defs = []  # (line, name, target)
    # Returns {name: earliest definition line}, not a bare set: an alias is in
    # effect only for lines READ after its definition, and a flat set promoted
    # every definition file-wide.  A call that PRECEDES its alias definition
    # was graded as an emission (#1032 round 7 P2).
    for ll in lx.logical:
        for seg in ll.segments:
            cmd, _redir = resolve_command(seg)
            lits = [_unquote_command_word(w) for w in seg.words]
            lits = [l for l in lits if l is not None]
            if cmd == "shopt" and "-s" in lits and "expand_aliases" in lits:
                if enabled_at is None:
                    enabled_at = ll.first_line
            elif cmd == "alias":
                for l in lits[1:]:
                    m = _ALIAS_RE.match(l)
                    if m:
                        defs.append((ll.first_line, m.group(1), m.group(2)))
    if enabled_at is None or not defs:
        return {}
    out = {}
    # A fixed point, so `alias a=b` / `alias b=echo` resolves however long the
    # chain is -- the same reason `discover_emitter_helpers` iterates.
    while True:
        grew = False
        for line, name, target in defs:
            # NOT `line < enabled_at`.  `alias` RECORDS the definition whether
            # or not expansion is on; `expand_aliases` only governs whether a
            # line being READ expands one.  So a definition that PREDATES the
            # `shopt` is still in effect at a later call site and does expand
            # there -- `alias leak=echo`, `shopt -s expand_aliases`,
            # `leak "$GH_TOKEN"` prints the credential, measured, and the
            # earlier ordering test discarded the definition and read clean
            # (#1032 round 6 P1).  `enabled_at is None` above is what keeps
            # `alias-without-expand-aliases` clean; this ordering test was
            # never what made the `shopt` gate real.
            if name in out:
                continue
            heads = _alias_target_commands(target)
            if any(
                h in EMITTERS or h in STDIN_ECHOERS or h in helpers or h in out
                for h in heads
            ):
                out[name] = min(out.get(name, line), line)
                grew = True
        if not grew:
            return out


def _alias_target_commands(target):
    """Every command word in an alias REPLACEMENT LIST.

    An alias target is a replacement LIST, not a single command: bash splices
    the whole text in, so `alias leak=':; echo'` runs `:` and then `echo`.
    Reading only the first command graded the alias on `:` and called it safe
    while the trailing emitter printed the credential (#1032 round 8 P1).
    """
    # Alias replacement text follows the ordinary shell's quote removal and
    # list-separator rules.  Reusing the lexer plus `resolve_command` handles
    # both halves together: `command "echo"` resolves to `echo`, while a `;`
    # inside a quoted argument stays data instead of inventing a second
    # command.  The previous regex split and `str.split()` did neither.
    out = []
    lx = Lexer(target)
    for ll in lx.logical:
        for seg in ll.segments:
            head, _redir = resolve_command(seg)
            if head and head != UNRESOLVED:
                out.append(head)
    return out


def _function_body_line_spans(text):
    """1-based line spans of every function BODY in this text.

    A `set +x` in a function body runs only if the function is CALLED, and
    whether it is called is control flow a source-text scanner does not model.
    Used to refuse an xtrace DISABLE from inside one -- see `_xtrace_delta`.
    """
    spans = []
    # Same command-position rule as `discover_emitter_helpers` (#1032 round 6
    # P1).  Here the cost of missing a definition runs the OTHER way: a body
    # this does not see is not a span, so a `set +x` inside it would be
    # CREDITED instead of refused -- a silent false negative, which is the
    # direction `xtrace-disable-in-called-function` exists to avoid.
    for m, _name, body in _iter_function_definitions(text):
        start_line = text.count("\n", 0, m.end()) + 1
        spans.append((start_line, start_line + body.count("\n")))
    return spans


def _xtrace_delta(ll, in_function):
    """The xtrace state change this LOGICAL LINE makes, or None.

    ASYMMETRIC on purpose, because the two directions have opposite risk:

      * ENABLING is believed wherever it is written.  A `set -x` the scanner
        credits that bash never executes costs a false positive on a line the
        author can pragma.
      * DISABLING is believed only from a line that is UNCONDITIONALLY
        executed at the top level -- the whole logical line is the `set` and
        nothing else, and it is not inside a function body.  A `set +x` the
        scanner credits that bash never executes costs a silent FALSE
        NEGATIVE, and it is trivially reachable: `set -x; f() { set +x; }`
        and `set -x; if false; then set +x; fi` both leave tracing ON at run
        time while a source-order reading turned it off (#1032 round 6 P1).

    So the rule that closes the bypass is not "model control flow" -- which a
    source-text scanner cannot do -- but "only an unconditional disable
    counts".  Anything else leaves tracing on, which is the fail-closed side.
    """
    real = [s for s in ll.segments if s.words]
    deltas = [_segment_sets_xtrace(s) for s in real]
    deltas = [d for d in deltas if d is not None]
    if not deltas:
        return None
    if True in deltas:
        return True
    # Every delta on this line is a disable.
    if len(real) != 1 or in_function:
        return None
    return False


def _shebang_enables_xtrace(text):
    first = text.split("\n", 1)[0]
    argv = _resolved_shebang_argv(first)
    if not argv or _basename(argv[0]) not in SHELL_INTERPRETERS:
        return False
    # `-o xtrace` is a PAIR, and bash accepts it on a `#!` line through
    # `env -S`.  Scanning only for an `x` inside a short-option word missed
    # `#!/usr/bin/env -S bash -o xtrace`, which starts the script traced, so
    # every later reference went to stderr expanded under a PASS (#1032
    # round 7 P1).
    words = argv[1:]
    i = 0
    while i < len(words):
        w = words[i]
        if w in ("-o", "+o"):
            if w == "-o" and i + 1 < len(words) and words[i + 1] == "xtrace":
                return True
            i += 2
            continue
        if w == "--xtrace":
            return True
        if w.startswith("-") and not w.startswith("--") and "x" in w[1:]:
            return True
        i += 1
    return False


def _text_enables_xtrace(text, outer_only=False):
    """Does this text turn xtrace ON anywhere in it?

    For deferred initialization, outer_only retains only writes in the
    existing lexer's outer scope. Default callers keep the aggregate source
    predicate; neither mode infers function invocation or callback timing.

    Used on DEFERRED text (`eval`, a trap action, `mapfile -C`), whose effect
    on the CURRENT shell outlives the deferred command.  Deliberately
    one-directional: an ENABLE is carried out, a DISABLE is not.  The two are
    not symmetric in cost -- crediting a disable that never runs is a silent
    false negative, while carrying an enable that never runs costs a visible
    finding the author can pragma -- which is the same asymmetry
    `xtrace-disable-in-called-function` already records.
    """
    try:
        lx = Lexer(text)
    except Exception:  # pragma: no cover - a text the lexer refuses
        return True  # unreadable deferred text: fail CLOSED
    for ll in lx.logical:
        for seg in ll.segments:
            if _segment_sets_xtrace(seg) is True and (
                not outer_only or seg.parent is None
            ):
                return True
    return False


def scan_text(text, path="<text>", _depth=0, _initial_xtrace=False):
    """Return (findings, pragma_errors)."""
    text = text.replace("\r\n", "\n").replace("\r", "\n")
    helpers = discover_emitter_helpers(text)
    lx = Lexer(text)
    findings = []
    pragma_errors = []
    if lx.unterminated_heredoc is not None:
        # The lexer reached end of file with a here-doc still open, so every
        # line after the opener was read as body text rather than as code.
        # That is discovery shrinking silently INSIDE a file, and it is
        # reported for the same reason `scanned 0 shell files` is.
        delim, opened_at = lx.unterminated_heredoc
        pragma_errors.append(
            "%s:%d: here-doc delimited by end of file -- the delimiter %r was "
            "never found, so the rest of the file was read as body text and "
            "not as code" % (path, opened_at, delim)
        )
    xtrace = _initial_xtrace or _shebang_enables_xtrace(text)
    effective_xtrace = xtrace
    fn_spans = _function_body_line_spans(text)
    aliases = _alias_emitters(lx, helpers)
    base_helpers = set(helpers)
    for ll in lx.logical:
        if ll.pragma_bare and not ll.pragma_reasons:
            pragma_errors.append(
                "%s:%d: %s: with no reason -- the reason is mandatory"
                % (path, ll.first_line, PRAGMA)
            )
        # xtrace is shell STATE and it changes WITHIN a logical line as well
        # as between them: `( set -x; : "$GH_TOKEN" )` is one line whose
        # second segment runs traced.  So the state is resolved per SEGMENT,
        # in source order, and each reference is graded under the state in
        # effect where it sits -- carrying one flag for the whole line read
        # `set -x` as taking effect only on the NEXT line and missed that one.
        # An alias is in effect only for a line READ after its definition, so
        # the helper set is rebuilt per logical line rather than promoted
        # file-wide.  `<=` and not `<`: a definition and a use on the SAME
        # line do not connect in bash, and refusing to model that is the
        # declared `alias-defined-and-used-on-one-line` conservatism, which
        # this must not silently retire.
        helpers = base_helpers | {
            n for n, dl in aliases.items() if dl <= ll.first_line
        }
        in_function = any(lo <= ll.first_line <= hi for lo, hi in fn_spans)
        line_delta = _xtrace_delta(ll, in_function)
        xtrace_at = {}
        effective_xtrace_at = {}
        effective_xtrace_scopes = {None: effective_xtrace}
        state = xtrace
        # `state` grades the segments of THIS line, including the ones inside a
        # subshell -- `( set -x; : "$PAT" )` really is traced.  `outer` is what
        # survives the line, and a subshell's option state does not: bash
        # discards it when the subshell exits, so `( set -x )` followed by
        # `: "$PAT"` emits nothing and the gate reported a finding (#1032
        # round 7 P2).
        outer = xtrace
        deferred_xtrace_scopes = set()
        for seg in ll.segments:
            # Reuse the lexer's parent lineage: a known enable in an outer
            # scope reaches later children, but a child enable does not escape
            # its subshell/capture or reach a sibling's shell state.
            scopes = [None]
            parent = seg.parent
            while parent is not None:
                scopes.append(parent.sid)
                parent = parent.parent
            xtrace_at[seg.sid] = state or any(
                scope in deferred_xtrace_scopes for scope in scopes
            )
            # Deferred initialization uses effective parent-scope state;
            # keep the legacy ordinary-reference map independent.
            effective_xtrace_at[seg.sid] = next(
                effective_xtrace_scopes[scope]
                for scope in scopes[1:] + [None]
                if scope in effective_xtrace_scopes
            )
            current_scope = seg.parent.sid if seg.parent is not None else None
            st = _segment_sets_xtrace(seg)
            if st is True:
                effective_xtrace_scopes[current_scope] = True
                state = True
                if not seg.parent_is_subshell:
                    outer = True
            elif st is False and line_delta is False:
                effective_xtrace_scopes[current_scope] = False
                state = False
                if not seg.parent_is_subshell:
                    outer = False
            # The same bounded extractor/enable predicate used below must
            # contribute before later segments consume this map. This retains
            # written enable evidence, not a claim that a trap/callback ran.
            if not ll.pragma_reasons and _depth < _DEFERRED_SHELL_DEPTH:
                deferred_operands = _deferred_shell_operands(seg)
                if any(_text_enables_xtrace(inner, outer_only=True)
                       for inner in deferred_operands):
                    effective_xtrace_scopes[current_scope] = True
                if any(_text_enables_xtrace(inner)
                       for inner in deferred_operands):
                    deferred_xtrace_scopes.add(
                        seg.parent.sid if seg.parent is not None else None
                    )
        effective_xtrace = effective_xtrace_scopes[None]
        if ll.pragma_reasons:
            # A pragma'd line is exempt, and so is any xtrace it turns on --
            # the exemption is the author's written statement about THIS line.
            xtrace = outer
            continue
        for ref in ll.refs:
            hit, why = reaches_output(ref, helpers)
            if not hit and xtrace_at.get(
                ref.seg.sid if ref.seg is not None else None, xtrace
            ):
                hit, why = True, (
                    "xtrace: `set -x` is in effect, so bash writes this "
                    "expanded command -- value included -- to stderr"
                )
            if hit:
                findings.append(Finding(path, ref.line, ref.name, why))
        if _depth < _DEFERRED_SHELL_DEPTH:
            for seg in ll.segments:
                for inner in _deferred_shell_operands(seg):
                    sub, sub_errors = scan_text(
                        inner, path=path, _depth=_depth + 1,
                        _initial_xtrace=effective_xtrace_at.get(
                            seg.sid, effective_xtrace
                        ),
                    )
                    # A discovery error inside the deferred text is discovery
                    # shrinking, exactly as it is at file level, so it is
                    # reported rather than dropped -- dropping it would make
                    # the one place the scanner admits it cannot read the
                    # source the one place that admission is invisible.
                    for e in sub_errors:
                        pragma_errors.append(
                            "%s:%d: inside deferred shell text: %s"
                            % (path, seg.line, e)
                        )
                    for f in sub:
                        findings.append(
                            Finding(
                                path,
                                seg.line,
                                f.name,
                                "deferred shell text run later by this "
                                "command: %s" % f.reason,
                            )
                        )
                    # xtrace set by DEFERRED code is a change to THIS shell
                    # and it outlives the deferred command: `eval 'set -x'`
                    # leaves tracing on, so every later reference is written
                    # to stderr expanded.  The recursive scan finds no
                    # credential in `set -x` itself and its state was
                    # discarded, so `eval 'set -x'` + `: "$GH_TOKEN"` read
                    # CLEAN (#1032 round 6 P1).  A `DEBUG` trap and
                    # `mapfile -C 'set -x'` are the same bypass, which is why
                    # this rides the deferred-operand walk that already covers
                    # all three rather than being a rule about `eval`.
                    if _text_enables_xtrace(inner):
                        state = True
                        if not seg.parent_is_subshell:
                            outer = True
        xtrace = outer
    return findings, pragma_errors


# -- discovery -------------------------------------------------------------

_ENV_OPTS_WITH_ARG = {"-u", "--unset", "-C", "--chdir", "-S", "--split-string"}


def _split_env_string(value):
    """Split one GNU `env -S` string, including its quote removal."""
    try:
        return shlex.split(value, comments=False, posix=True)
    except ValueError:
        return None


def _resolved_shebang_argv(first_line):
    """Return the resolved interpreter argv from a `#!` line, or None.

    `None` means "this line named no interpreter I can resolve", and the
    caller then falls through to the extension and finally to SCANNING the
    file.  Nothing here may ever cause a file to be skipped: reducing
    `#!/usr/bin/env -S bash -e` to `-S` is precisely how #1012 turned a live
    `echo "$GH_TOKEN"` into `scanned 0 shell files` and `PASS`.

    Exercised directly by `_shebang_cases()`, not only through the
    file-selection corpus, so the `env` resolution is pinned on its own.
    """
    line = first_line.rstrip("\n").rstrip("\r")
    if not line.startswith("#!"):
        return None
    raw = line[2:].strip()
    argv = raw.split()
    if not argv:
        return None
    # Quote removal belongs to `env -S`, not to the kernel's ordinary shebang
    # parsing.  `#!/bin/bash '-x'` hands bash literal quote bytes and must not
    # be mistaken for xtrace; `#!/usr/bin/env -S bash '-x'` asks env to remove
    # them and does enable it.
    if _basename(argv[0]) == "env" and any(
        word == "-S"
        or word.startswith("-S")
        or word == "--split-string"
        or word.startswith("--split-string=")
        for word in argv[1:]
    ):
        argv = _split_env_string(raw)
        if not argv:
            return None
    guard = 4
    while guard > 0:
        guard -= 1
        base = _basename(argv[0])
        if base != "env":
            return argv
        argv = argv[1:]
        # consume env's own options and assignments
        while argv:
            a = argv[0]
            if a == "--":
                argv = argv[1:]
                break
            # `-S STR` SPLITS STR into separate arguments that `env` itself
            # then processes -- GNU `env --help`: "process and split S into
            # separate arguments; used to pass multiple arguments on shebang
            # lines".  So the split words re-enter THIS loop (`continue`), not
            # the interpreter position.  Breaking to the outer loop instead
            # read the first split word as the interpreter, so the valid
            # `#!/usr/bin/env -S --default-signal=PIPE bash` resolved to
            # `--default-signal=PIPE`; a `.py` file carrying that shebang then
            # classified NON-SHELL on its extension and a live
            # `echo "$GH_TOKEN"` inside it was never read (#1032 round 4 P1).
            # An option inside the split string that this resolver does not
            # model still falls to the `-`-prefixed branch below and returns
            # None, which is the fail-safe answer, not a skip.
            if a.startswith("--split-string="):
                split = _split_env_string(a.split("=", 1)[1])
                if split is None:
                    return None
                argv = split + argv[1:]
                continue
            if a in ("-S", "--split-string"):
                if len(argv) < 2:
                    return None
                # The whole shebang was quote-decoded above, so the words
                # following `-S` are already the arguments GNU env produces.
                # Keeping the original `.split()` here retained quote bytes:
                # `bash '-x'` launched traced but the scanner looked for `x`
                # in the literal word `'-x'` and reported clean.
                argv = argv[1:]
                continue
            if a.startswith("-S"):
                split = _split_env_string(a[2:])
                if split is None:
                    return None
                argv = split + argv[1:]
                continue
            if a in _ENV_OPTS_WITH_ARG:
                if len(argv) < 2:
                    return None
                argv = argv[2:]
                continue
            if a.startswith("--unset=") or a.startswith("--chdir="):
                argv = argv[1:]
                continue
            if a in ("-i", "--ignore-environment", "-0", "--null", "-v", "--debug"):
                argv = argv[1:]
                continue
            if re.match(r"^[A-Za-z_][A-Za-z0-9_]*=", a):
                argv = argv[1:]
                continue
            if a.startswith("-"):
                # An env option this resolver does not model.  Return None so
                # the caller falls through to the extension and finally to
                # SCANNING the file, rather than reducing the interpreter to
                # the option itself -- which is exactly how `env -S` made a
                # file invisible in #1012.
                return None
            break
        if not argv:
            return None
    return None


def resolve_shebang(first_line):
    """Return the interpreter basename a `#!` line resolves to, or None."""
    argv = _resolved_shebang_argv(first_line)
    return _basename(argv[0]) if argv else None


def classify_file(path):
    """Return "shell" or "non-shell".  Raises CheckError when unclassifiable."""
    try:
        with open(path, "rb") as fh:
            head = fh.read(8192)
    except OSError as exc:
        raise CheckError("unreadable: %s" % exc)
    try:
        first = head.split(b"\n", 1)[0].decode("utf-8", "replace")
    except Exception as exc:  # pragma: no cover - decode never raises here
        raise CheckError("undecodable head: %s" % exc)
    interp = resolve_shebang(first)
    if b"\x00" in head:
        # A NUL is strong evidence of a binary, but it is EVIDENCE, not an
        # override: bash happily executes a `.sh` file with a stray NUL in it,
        # and letting the heuristic win meant `echo "$GH_TOKEN"` followed by a
        # NUL byte was skipped before its extension or shebang was ever
        # consulted, and `--scan` reported PASS (#1032 round 7 P1).  An
        # EXPLICIT declaration of shell -- a shell extension or a resolved
        # shell shebang -- outranks it; everything else (a real PNG, a `.txt`
        # with a NUL) is still non-shell on the same heuristic as before.
        if interp in SHELL_INTERPRETERS:
            return "shell"
        if os.path.splitext(path)[1].lower() in SHELL_EXTS:
            return "shell"
        return "non-shell"
    if interp in SHELL_INTERPRETERS:
        return "shell"
    if interp in NON_SHELL_INTERPRETERS:
        return "non-shell"
    ext = os.path.splitext(path)[1].lower()
    if ext in SHELL_EXTS:
        return "shell"
    # A `#!` line is PRESENT but this resolver could not settle it.  The
    # extension must not decide that case: the kernel obeys the shebang and
    # ignores the name, so trusting `.py` over an unresolved `#!` is the one
    # combination that can skip a file bash actually executes.  `resolve_
    # shebang` returning None for an unmodelled `env` option is the fail-SAFE
    # answer only if the caller then READS the file, which is what this does
    # (#1032 round 4 P1).  A file with no `#!` at all is unaffected -- the
    # extension keeps deciding it.
    if first.startswith("#!"):
        return "shell"
    if ext in NON_SHELL_EXTS:
        return "non-shell"
    # Neither the shebang nor the extension settled it.  The FAIL-CLOSED
    # answer for a scanner is to READ the file, never to skip it: a file bash
    # will execute must be a file the gate reads, and a shell fragment with
    # neither a shebang nor a `.sh` (a sourced snippet, a frozen fixture
    # copied without its first line) is exactly what #1012's discovery
    # dropped on the floor.  Scanning a non-shell text file costs at most a
    # visible finding that a pragma or a rename settles; skipping a shell
    # file costs a silent PASS, which is the #951 shape this gate exists to
    # stop.  So the fallback is deliberately asymmetric.
    return "shell"


def _command_index(words, commands):
    """Index of the resolved command word in `words`, or None."""
    for idx, word in enumerate(words):
        lit = _unquote_command_word(word)
        if lit is not None and _basename(lit) in commands:
            return idx
    return None


def _command_arguments(words, start):
    """Yield `(raw, literal)` arguments after shell redirections."""
    skip_next = False
    for word in words[start:]:
        if skip_next:
            skip_next = False
            continue
        if word in ("{", "}", "<<"):
            continue
        if word == "<<<":
            skip_next = True
            continue
        match = _REDIR_RE.match(word)
        if match:
            if match.end() == len(word):
                skip_next = True
            continue
        yield word, _unquote_command_word(word)


def _interpreter_script_operand(arguments):
    """Return a literal script operand from shell-interpreter arguments."""
    skip_next = False
    options = True
    for _raw, lit in arguments:
        if skip_next:
            skip_next = False
            continue
        if options and lit == "--":
            options = False
            continue
        if options and (
            lit in ("-c", "-s", "--command", "--stdin")
            or (
                lit
                and lit.startswith("-")
                and not lit.startswith("--")
                and ({"c", "s"} & set(lit[1:]))
            )
        ):
            # `-c` takes shell TEXT and `-s` reads stdin.  Later words are $0
            # / positional parameters, never script paths.
            return None
        if options and lit in (
            "-o", "+o", "-O", "+O", "--rcfile", "--init-file"
        ):
            skip_next = True
            continue
        if options and lit and (lit.startswith("-") or lit.startswith("+")):
            continue
        # The first non-option word is the script.  An expansion is not a
        # literal path and remains a declared discovery residue.
        return lit
    return None


def shell_file_operands(text):
    """Return `(literal path, invoking dialect)` for executed shell files.

    `.` / `source` return dialect None because they inherit the caller.  A
    literal interpreter invocation returns its named dialect: `bash leak.py`
    executes shell source even though the extension table calls the operand
    Python.  Discovery previously promoted only sourced fragments and silently
    skipped this equivalent execution path (#1032 fresh Codex P1).

    An operand carrying an expansion (`. "$LIB_DIR/common.sh"`) is not a
    literal and is skipped -- a declared residue, not a guess.

    ONE leading `--` is the option terminator and is stepped over; the next
    one is the FILENAME.  Measured under bash 5.3: `. -- ./lib.env` sources
    `lib.env`, and `. -- -- ./lib.env` sources a file literally named `--`.
    Taking the first word after the builtin unconditionally recorded `--` as
    the operand, so the fragment behind it kept its non-shell classification
    and was never read while bash executed it (#1032 round 3 P1).
    """
    out = []
    lx = Lexer(text)
    for ll in lx.logical:
        for seg in ll.segments:
            cmd, _redir = resolve_command(seg)
            if cmd not in (".", "source") and cmd not in SHELL_INTERPRETERS:
                continue
            words = list(seg.words)
            idx = _command_index(words, frozenset({cmd}))
            if idx is None:
                continue
            arguments = list(_command_arguments(words, idx + 1))
            if cmd in (".", "source"):
                saw_terminator = False
                for _raw, lit in arguments:
                    if lit == "--" and not saw_terminator:
                        saw_terminator = True
                        continue
                    if lit:
                        out.append((lit, None))
                    break
            else:
                lit = _interpreter_script_operand(arguments)
                if lit:
                    out.append((lit, cmd))
    return out


def source_operands(text):
    """Compatibility view used by the direct source-operand assertions."""
    return [path for path, dialect in shell_file_operands(text) if dialect is None]


def _read_text(path):
    with open(path, "r", encoding="utf-8", errors="replace") as fh:
        return fh.read()


def discover_shell_files(root):
    """Walk the scan roots.  Every failure is fatal; nothing is skipped."""
    shell = []
    errors = []
    present_roots = 0
    walked = {}  # realpath -> (path, "shell" | "non-shell")
    for rel in SCAN_ROOTS:
        base = os.path.join(root, rel)
        if not os.path.isdir(base):
            if os.path.lexists(base):
                # The path EXISTS and is not a directory -- a regular file, a
                # device, a symlink to nothing.  Skipping it silently is the
                # same shrink as the unreadable directory above, and the
                # zero-file guard cannot catch it because the OTHER root's
                # files keep the count non-zero and `present_roots` non-zero
                # (#1032 round 3 M2).  Whatever it is, the gate did not look
                # inside `scripts/**`, and it must say so.
                errors.append(
                    "%s: scan root exists but is not a directory -- refusing "
                    "to report a clean tree over a root the gate never "
                    "walked" % base
                )
            continue
        present_roots += 1

        def _walk_error(exc, _base=base):
            # `os.walk` swallows every OSError it raises unless a callback is
            # given: an unreadable subdirectory yields NOTHING and the walk
            # continues as if the subtree were empty.  A gate whose discovery
            # can shrink in silence is the #951 shape it exists to stop, so
            # the failure is recorded and the scan reports it (#1032 F9).
            errors.append(
                "%s: unreadable directory: %s"
                % (getattr(exc, "filename", None) or _base, exc)
            )

        # Symlinks ARE followed, because a symlinked shell file is a file bash
        # will execute.  `seen` keeps a directory cycle from looping forever;
        # a gate that hangs is a gate that never reports.
        seen = set()
        for dirpath, dirnames, filenames in os.walk(
            base, followlinks=True, onerror=_walk_error
        ):
            try:
                key = os.path.realpath(dirpath)
            except OSError as exc:
                errors.append("%s: unresolvable directory: %s" % (dirpath, exc))
                dirnames[:] = []
                continue
            if key in seen:
                dirnames[:] = []
                continue
            seen.add(key)
            dirnames[:] = sorted(d for d in dirnames if d != ".git")
            for name in sorted(filenames):
                p = os.path.join(dirpath, name)
                try:
                    st = os.stat(p)
                except OSError as exc:
                    errors.append("%s: unstattable: %s" % (p, exc))
                    continue
                if not stat.S_ISREG(st.st_mode):
                    errors.append("%s: not a regular file" % p)
                    continue
                try:
                    kind = classify_file(p)
                except CheckError as exc:
                    errors.append("%s: %s" % (p, exc))
                    continue
                try:
                    walked[os.path.realpath(p)] = (p, kind)
                except OSError:
                    pass
                if kind == "shell":
                    shell.append(p)

    # A file this walk called non-shell but a shell file EXECUTES is shell:
    # `. ./lib.env` and `bash ./lib.py` both run their operand as shell source,
    # whatever the extension table said.  Resolved to a fixed point, because a
    # promoted fragment can execute another.
    pending = list(shell)
    promoted = set()
    unmodelled_promotions = set()
    while pending:
        origin = pending.pop()
        try:
            text = _read_text(origin)
        except OSError as exc:
            errors.append("%s: unreadable: %s" % (origin, exc))
            continue
        for operand, dialect in shell_file_operands(text):
            for cand in (
                os.path.join(os.path.dirname(origin), operand),
                os.path.join(root, operand),
            ):
                try:
                    key = os.path.realpath(cand)
                except OSError:
                    continue
                entry = walked.get(key)
                if entry is None:
                    continue
                if dialect in UNMODELLED_SHELL_DIALECTS:
                    marker = (key, dialect)
                    if marker not in unmodelled_promotions:
                        unmodelled_promotions.add(marker)
                        errors.append(
                            "%s: executed through %s, a dialect whose output "
                            "builtins this gate does not model -- refusing to "
                            "report a clean tree over the promoted file"
                            % (entry[0], dialect)
                        )
                if entry[1] == "shell" or key in promoted:
                    break
                promoted.add(key)
                shell.append(entry[0])
                pending.append(entry[0])
                break
    return shell, errors, present_roots


def unmodelled_dialect(path, text):
    """Name this file's shell dialect when the emitter model cannot read it.

    Extension first, then the shebang: both are how discovery SELECTED the
    file in the first place, so both are how it can say the selection landed
    on a dialect it grades with the wrong model.  Returns None for bash/sh and
    everything else the model does read.
    """
    ext = os.path.splitext(path)[1].lower()
    if ext in UNMODELLED_SHELL_EXTS:
        return ext.lstrip(".")
    interp = resolve_shebang(text.split("\n", 1)[0])
    if interp in UNMODELLED_SHELL_DIALECTS:
        return interp
    return None


def scan_tree(root):
    """Scan a tree.  Returns (findings, errors, count-of-shell-files)."""
    shell, errors, present_roots = discover_shell_files(root)
    if present_roots == 0:
        errors.append(
            "none of the scan roots %s exist under %s -- refusing to report a "
            "clean tree the gate never looked at" % (list(SCAN_ROOTS), root)
        )
    findings = []
    for p in shell:
        try:
            with open(p, "r", encoding="utf-8", errors="replace") as fh:
                text = fh.read()
        except OSError as exc:
            errors.append("%s: unreadable: %s" % (p, exc))
            continue
        rel = os.path.relpath(p, root)
        dialect = unmodelled_dialect(p, text)
        if dialect is not None:
            # Still scanned below -- the bash model catches every construct
            # the dialects share -- but never reported CLEAN, because the
            # output builtins that differ (`print`) are outside `EMITTERS`.
            errors.append(
                "%s: written in %s, a dialect whose output builtins this gate "
                "does not model -- `print -r -- \"$GH_TOKEN\"` writes the "
                "value and grades SAFE here, so a clean result over this file "
                "would not mean what it says.  Rewrite it in bash/sh, or "
                "extend EMITTERS with cases measured under %s."
                % (rel, dialect, dialect)
            )
        f, pragma_errors = scan_text(text, rel)
        findings.extend(f)
        errors.extend(pragma_errors)
    if not shell and not errors:
        errors.append(
            "scanned 0 shell files under %s -- a scan that selects no files is "
            "a discovery failure, never a clean tree" % root
        )
    return findings, errors, len(shell)


# ==========================================================================
# The execution oracle and the differential corpus
# ==========================================================================

# An obviously fake constant, never real credential material (#996 "Not in
# scope").  Deliberately word-free so that a short window of it cannot collide
# with ordinary program output -- the oracle looks for windows as well as the
# whole string, because `${VAR:0:8}` is a partial leak and a whole-string grep
# would call it clean.
#
# `SENTINEL_WINDOW` is the oracle's MINIMUM DETECTABLE FRAGMENT, and it is a
# stated bound rather than an implementation detail: a run of fewer than that
# many consecutive credential characters reaching a stream is a leak the
# oracle CANNOT SEE.  It was 8, and at 8 `echo "${GH_TOKEN:0:7}"` -- seven
# credential characters on stdout -- measured CLEAN, so the scanner's correct
# finding would have been recorded as scanner conservatism: a real leak filed
# under the register of things the gate is too strict about (#1032 round 3
# P2).  The floor is now 4, which is what `${VAR:0:4}` costs, and BELOW it the
# residue is declared for what it is -- a limit of the MEASUREMENT, not of the
# scanner -- and pinned by `_sentinel_window_cases`, which also asserts the
# collision-resistance property the floor rests on: every window of this
# sentinel carries both an upper-case letter and a digit, a shape that does
# not occur in the temp paths and bash diagnostics the fixtures also emit.
# Lowering the floor can only make the oracle see MORE, so it can surface a
# scanner false negative and can never invent a false positive.
#
# It is ONE value, and its SHAPE is load-bearing.  This one is LETTER-LEADING,
# so `echo $((GH_TOKEN))` resolves the operand as a name, finds it unset and
# evaluates to 0 -- measuring CLEAN.  A DIGIT-LEADING NON-NUMERIC value on the
# same line puts the sentinel on STDERR twice, through bash's own `value too
# great for base` diagnostic, and the oracle greps stderr.  (An all-digit
# value evaluates as a number and reads clean again -- the shapes are not
# interchangeable, which is the point of sweeping them.)  Every verdict this
# records is therefore quantified over this shape and no other; sweeping the
# corpus across letter-leading, digit-leading and all-digit values is #1036.
# `sentinel_shape()` below DERIVES the shape from this constant instead of
# restating it, and `--self-test` prints it, so the limit stated in the header
# cannot drift away from the value the fixtures actually carry.
SENTINEL = "Zq7Xf2Lp9Vt4Rk8Nb3Md6Wc1Ys5Hj0Gr"
SENTINEL_WINDOW = 4
_SENTINEL_WINDOWS = tuple(
    SENTINEL[i : i + SENTINEL_WINDOW]
    for i in range(len(SENTINEL) - SENTINEL_WINDOW + 1)
)


def sentinel_shape():
    """Name the ONE value shape the oracle samples, derived from `SENTINEL`.

    Written as a derivation rather than a constant so that changing `SENTINEL`
    changes what `--self-test` reports, instead of leaving the header's stated
    limit describing a value the fixtures no longer carry.  The three names
    are the three shapes #1036 asks the corpus to sweep.
    """
    if not SENTINEL:
        return "empty"
    if SENTINEL.isdigit():
        return "all-digit"
    if SENTINEL[0].isdigit():
        return "digit-leading non-numeric"
    if SENTINEL[0].isalpha():
        return "letter-leading"
    return "other-leading"


def sentinel_reached(*streams):
    """Ground truth: did any recognisable piece of the sentinel reach a stream?

    RECOGNISABLE has a floor, and the floor is `SENTINEL_WINDOW` consecutive
    characters.  Below it this returns False on a value that really did reach
    a stream -- that is a limit of the MEASUREMENT, not conservatism in the
    scanner, and `_sentinel_window_cases` pins both sides of the boundary so
    the bound is asserted rather than merely written down.
    """
    for s in streams:
        if not s:
            continue
        for w in _SENTINEL_WINDOWS:
            if w in s:
                return True
    return False

PROLOGUE = (
    "#!/usr/bin/env bash\n"
    "# Disposable oracle fixture. The value below is an obviously fake\n"
    "# constant, never real credential material (#996 Not in scope).\n"
    "GH_TOKEN='" + SENTINEL + "'\n"
    "OP_PREFLIGHT_REVIEWER_PAT='" + SENTINEL + "'\n"
)

MUST_FLAG = "flag"
MUST_NOT_FLAG = "clean"

# (id, disposition, body)  -- body is appended to PROLOGUE.
